/**
 * @module widget/rfFBViewer
 * @desc FormBuilder Viewer Control
 *
 */
IG$.rfFBViewer = function (instance, container, sop, owner, rpt) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	me.owner = owner;
	me.reportoption = rpt.reportoption;
	
//	if (me.owner && me.owner.box)
//	{
//		me.owner.box.bind("updatecomplete", function() {
//			me.validateItems();
//		});
//	}
	
	me.updateValues = true;
	me.active = null;
	me.validated = false;
	me.validateFilter = true;
	me.f_run = true;
	
	me.$init();
};

IG$.rfFBViewer.prototype = {
	$init: function() {
		var me = this;
		me.contentarea = $("<div class='igc-rpt-view'></div>").appendTo(me.container);
		
		// me.validateItems();
	},
	
	/**
	 * validate and execute report inside with timer 50 milisecond 
	 */
	executeItem: function() {
		var me = this;
		
		if (me.validateFilter || me.f_run)
		{
			me.f_run = false;
			
			clearTimeout(me._validateCall);
			
			me._validateCall = setTimeout(function() {
				me.executeValidate();
			}, 50);
		}
	},
	
	/**
	 * execute report immediately. Called from executeItem with timer
	 */
	executeValidate: function() {
		var me = this,
			i,
			sheet, sop;
		
		if (!me.fbviewer)
		{
			me.validateItems();
		}
		else
		{
		}
		
		me._directFilter = null;
		me.validateFilter = false;
	},
	
	removeObj: function() {
	},
	
	validateItems: function(runall, isloading) {
		var me = this,
			sop = me.sheetoption.model,
			run = !isloading && (me.btabrun || runall);
			
		if (sop && sop.docid)
		{
			sop.formbuilder = sop.formbuilder || {};
			if (sop.formbuilder.item && sop.formbuilder.item.uid)
			{
				if (!me.fbviewer)
				{
					me.validated = true;
					
					var contaner = me.contentarea;
					
					if (me.__dx != true)
					{
						me.fbviewer = new IG$.formViewer({
							instance: me.instance,
							uid: sop.formbuilder.item.uid,

							header: false,
							hiddenstatusbar: true,
							hiddentoolbar: true,
							border: 0,
							vmode: 1,
							frameHeader: false,
							cmode: 1,
							cvmode: me.cvmode,
							width: me._cw,
							height: me._ch,
							renderTo: me.contentarea[0],
							sheetobj: me,
							reportoption: me.reportoption,
							sheetoption: me.sheetoption
						});
						
						if (run || isloading)
						{
							me.fbviewer.on("_lc0", function() {
								me.fbviewer.un("_lc0");
								
								if (isloading)
								{
									me.container.trigger("i_ready");
								}
								
								if (run)
								{
									me.validateFilter = true;
									me.executeItem();
								}
							});
						}
						
						me._directFilter = null;
						me.validateFilter = false;
					}
				}
				else
				{
					me.container.trigger("i_ready");
				}
				
				if (me.fbviewer)
				{
					if (me.fbviewer.uid != sop.formbuilder.item.uid)
					{
						me.fbviewer.uid = sop.formbuilder.item.uid;
						me.fbviewer.init_f();
					}
					else if (!isloading && me.fbviewer.__loaded)
					{
						me.fbviewer.init_f();
					}
					me.validateFilter = false;
				}
			}
		}
	},
	
	setSize: function(w, h, force) {
		var me = this,
			c = me.contentarea;
			
		me.pw = me.pw || 0;
		me.ph = me.ph || 0;
		
		me._cw = w;
		me._ch = h;
		
		if (me.fbviewer && (force || (Math.abs(me.pw - w) > 5 || Math.abs(me.ph - h) > 5)))
		{
			me.pw = w;
			me.ph = h;
			IG$.j$ext._w(c, w);
			IG$.j$ext._h(c, h);
			
			if (me.fbviewer)
			{
				me.fbviewer.setSize(w, h);
			}
		}
	},
	
	updateFilterContent: function(finfo) {
	}
};