

/**
 * text control
 */
IG$._FC_text = $s.extend(IG$._baseFC, {
	objtype: "text",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	properties: [
		{name: "text", type: "string"},
		{name: "placeholder", type: "string"}
	],
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			rangevalue = fmodel.rangevalue,
			rangelabel = me.rangelabel,
			_init_value = fmodel._init_value || fmodel.initial_values,
			ui = $("<div class='idv-sel-combo'></div>").appendTo(container),
			// ui_tr = $("tr", ui),
			m1,
			m2 = null,
			ml,
			Lt, Dt, S,
			fid = me._get_id(),
			fid2;
			
		Lt = (me.getRangeLabel(rangelabel, 0, 0, rangevalue));
			
		if (Lt)
		{
			Dt = $(Lt.d).appendTo(ui);
			Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
		}
		
		me.mp$ = me.createTextField(ui, Lt ? Lt.d : "");
		// <span class='mdc-line-ripple'></span>
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$);
		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$);

		Lt = (me.getRangeLabel(rangelabel, 0, 1, rangevalue));
		
		if (Lt)
		{
			Dt = $(Lt.d).appendTo(ui);
			Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
		}
		
		if (rangevalue)
		{
			fid2 = me._get_id();

			Lt = (me.getRangeLabel(rangelabel, 1, 2, rangevalue));
			if (Lt)
			{
				S = $("<div class='igc-f-range-label-td'></div>").appendTo(ui);
				Dt = $(Lt.d).appendTo(S);
				Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
			}
			
			Lt = (me.getRangeLabel(rangelabel, 2, 0, rangevalue));
			if (Lt)
			{
				Dt = $(Lt.d).appendTo(ui);
				Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
			}
			
			me.mp2$ = me.createTextField(ui, Lt ? Lt.d : "");
			lbl2$ = me.lbl2$ = $(".mdc-floating-label", me.mp2$);
			me.mp2$ = mdc.textField.MDCTextField.attachTo(me.mp2$);
			
			Lt = (me.getRangeLabel(rangelabel, 2, 1, rangevalue));
			
			if (Lt)
			{
				Dt = $(Lt.d).appendTo(ui);
				Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
			}
		}
		
		ml = rangevalue ? [me.mp$, me.mp2$] : [me.mp$];
		
		$.each(m1, function(i, k) {
			k.addEventListener("keyup", function(event) {
				if (event.which == 13)
				{
					me.trigger("change_val");
				}
			})
		});
		
		if (_init_value && _init_value.length)
		{
			// $("[name=c_m1]", m1).val(me.getDefaultValue(fitem, 0));
			var dvalue = me.getDefaultValue(fitem, 0);
			if (me.mp$)
				me.mp$.value = dvalue;
			me.trigger("change_val");
		}
		return ui;
	},
	updateValue: function(value) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			sctrls = [me.mp$];
			
		if (fmodel.rangevalue)
		{
			sctrls.push(me.mp2$);
		}
		
		$.each(sctrls, function(m, mui) {
			var tval = mui.value;
			
			if (tval)
			{
				value.push({code: tval, value: tval});
			}
		});
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			sctrl1;
		sctrl1 = me.mp$;
		sctrl1.value = values[0];
		if (fmodel.rangevalue)
		{
			sctrl2 = me.mp2$;
			sctrl2.value = values[1];
		}
	},
	clear: function(trigger) {
		var me = this,
			ui = me.ui,
			fitem = me.fitem,
			sctrls = [me.mp$];
		if (fitem.rangevalue)
		{
			sctrls.push(me.mp2$);
		}
		
		$.each(sctrls, function(m, mi) {
			mi.value = "";
		});
		
		me.trigger("change_val");
	},
	$setProp: function(fitem, key, value) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			sctrls = [me.mp$];
			
		if (fmodel.rangevalue)
		{
			sctrls.push(me.mp2$);
		}
		
		switch(key)
		{
		case "placeholder":
			$.each(sctrls, function(m, mui) {
				mui.placeholder = value;
			});
			break;
		case "text":
			me.setValue([value]);
			break;
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["text"] = new IG$._FC_text();