IG$.d$ValSel = $s.extend($s.panel, {
	field: null,
	
	layout: {
		type: "hbox",
		align: "stretch"
	},
	
	init_f: function() {
		// this.getValLst();
		var me = this,
			initial_values = me.initial_values,
			ndp = [],
			rec,
			i;
			
		me.down("[name=_3]").setValue("START");
		
		if (initial_values && initial_values.length)
		{
			for (i=0; i < initial_values.length; i++)
			{
				rec = initial_values[i];
				if (rec && rec.code)
				{
					ndp.push({
						code: rec.code,
						text: rec.text || rec.code
					});
				}
			}
			me.down("[name=_2]").store.loadData(ndp);
		}
	},
	
	getValLst: function() {
		var me = this,
			callback;
		
		if (me.prompt)
		{
			callback = new IG$.callBackObj(me, me.rs_getValLst, prompt);
			me.prompt.loadData(me, callback);
		}
		else if (me.field)
		{
			var content = {},
				obj,
				req = new IG$._rpc$(),
				keyword = me.down("[name=_4]").getValue(),
				_3 = me.down("[name=_3]").getValue(),
				meta_type = "filter";
			
			if (keyword)
			{
				content.operator = "LIKE";
				content.ftype = "condition";
				
				if (keyword.indexOf("%") < 0)
				{
					switch (_3)
					{
					case "INCLUDE":
						keyword = "%" + keyword + "%";
						break;
					case "START":
						keyword = keyword + "%";
						break;
					case "END":
						keyword = "%" + keyword;
						break;
					}
				}
				
				content.values = [{code: keyword}];
			}
			
			obj = {
				uid: (me.field ? me.field.uid : me.prompt.name), 
				option: "valuelist"
			};
			
			if (me.meta_type == "sql_report" && me.reportoption)
			{
				meta_type = "sql_report";
				content = me.reportoption.getCurrentPivot();
			}
			
			req.init(me, 
				{
					ack: "olapservice",
					payload: obj,
					mbody: content,
					meta_type: meta_type
				}, me, me.rs_getValLst, null, (me.field ? me.field.uid : me.prompt.name) );
			req.send();
		}
	},
	
	rs_getValLst: function(jdoc, uid) {
		var result = jdoc,
			inline_data = result.inline_data,
			dp = [],
			i,
			vgrid = this.down("[name=_1]");
		
		for (i=0; i < inline_data.length; i++)
		{
			dp.push({
				code: inline_data[i][0],
				text: inline_data[i][1] || inline_data[i][0]
			});
		}
			
		vgrid.store.loadData(dp);
	},
	
	selectItem: function(allvalue) {
		var i,
			vgrid = this.down("[name=_1]"),
			vstore = vgrid.store,
			vitems = vstore.data.items,
			sgrid = this.down("[name=_2]"),
			sstore = sgrid.store,
			sitems = sstore.data.items,
			move, d;
		
		if (allvalue == false)
		{
			var selected = vgrid.selModel.selected.items;
			
			if (selected && selected.length > 0)
			{
				for (i=selected.length-1; i >= 0; i--)
				{
					d = selected[i];
					vstore.remove(d);
					sstore.insert(0, d.data);
				}
			}
		}
		else
		{
			for (i=vitems.length-1; i>=0 ; i--)
			{
				d = vitems[i];
				vstore.remove(d);
				sstore.insert(0, d.data);
			}
		}
	},
	
	removeItem: function(allvalue) {
		var i,
			vgrid = this.down("[name=_1]"),
			vstore = vgrid.store,
			vitems = vstore.data.items,
			sgrid = this.down("[name=_2]"),
			sstore = sgrid.store,
			sitems = sstore.data.items,
			move, d;
		
		if (allvalue == false)
		{
			var selected = sgrid.selModel.selected.items;
			
			if (selected && selected.length > 0)
			{
				for (i=selected.length-1; i >= 0; i--)
				{
					d = selected[i];
					sstore.remove(d);
					vstore.insert(0, d.data);
				}
			}
		}
		else
		{
			for (i=sitems.length-1; i>=0; i--)
			{
				d = sitems[i];
				sstore.remove(d);
				vstore.insert(0, d.data);
			}
		}
	},
	
	initComponent: function() {
		
		this.items = [
			{
				xtype: "container",
				layout: {
					type: "vbox",
					align: "stretch"
				},
				flex: 1,
				padding: ig$.padding,
				defaults: {
					anchor: "100%"
				},
				items: [
					{
						xtype: "fieldcontainer",
						layout: {
							type: "hbox",
							align: "stretch"
						},
						fieldLabel: IRm$.r1("L_BTN_SEARCH"),
						labelWidth: 35,
						items: [
							{
								xtype: "combobox",
								name: "_3",
								queryMode: 'local',
								fieldLabel: "",
								displayField: 'name',
								valueField: 'value',
								editable: false,
								autoSelect: false,
								
								width: 100,
								
								store: {
									fields: [
										"name", "value"
									],
									data: [
										{name: "Include", value: "INCLUDE"},
										{name: "Start", value: "START"},
										{name: "End", value: "END"}
									]
								}
							},
							{
								xtype: "textfield",
								name: "_4",
								flex: 1,
								emptyText: IRm$.r1("L_SEARCH_KWD"),
								enableKeyEvents: true,
								listeners:{
									keydown: function(tobj, e, eopts) {
										if (e.keyCode == 13)
										{
											this.getValLst();
										}
									},
									scope: this
								}
							},
							{
								xtype: "button",
								iconCls: "icon-toolbar-search",
								tooltip: IRm$.r1("B_SEARCH"),
								width: 20,
								handler: function() {
									this.getValLst();
								},
								scope: this
							}
						]
					},
					{
						xtype: 'grid',
						name: "_1",
						store: {
							fields: [
								{name: 'code'},
								{name: 'text'}
							]
						},
						stateful: true,
						flex: 1,
						columnLines: true,
						selType: "checkboxmodel",
						selModel: {
							checkSelector: ".x-grid-cell"
						},
						
						columns: [
							{
								text: IRm$.r1("B_CODE"),
								flex: 1,
								sortable: true,
								dataIndex: 'code'
							},
							{
								text: IRm$.r1("B_TEXT"),
								flex: 1,
								sortable: true,
								dataIndex: 'text'
							}
						],
						viewConfig: {
							stripeRows: true
						}
					}
				]
			},
			{
				layout: {
					type: 'vbox',
					align: 'stretch',
					pack: 'center'
				},
				items: [
					{
						xtype: "container",
						flxe: 1
					},
					{
						xtype: 'button',
						text: '>>',
						handler:function() {
							this.selectItem(true);
						},
						scope: this
					},
					{
						xtype: 'button',
						text: '>',
						handler:function() {
							this.selectItem(false);
						},
						scope: this
					},
					{
						xtype: 'button',
						text: '<',
						handler:function() {
							this.removeItem(false);
						},
						scope: this
					},
					{
						xtype: 'button',
						text: '<<',
						handler:function() {
							this.removeItem(true);
						},
						scope: this
					},
					{
						xtype: "container",
						flex: 1
					}
				]
			},
			{
				xtype: "container",
				flex: 1,
				layout: {
					type: "vbox",
					align: "stretch"
				},
				border: 1,
				bodyPadding: 6,
				items: [
					{
						xtype: 'grid',
						name: '_2',
						store: {
							fields: [
								{name: 'code'},
								{name: 'text'}
							]
						},
						stateful: true,
						flex: 1,
						columnLines: true,
						selType: "checkboxmodel",
						selModel: {
							checkSelector: ".x-grid-cell"
						},
						columns: [
							{
								text: IRm$.r1("B_CODE"),
								flex: 1,
								sortable: false,
								dataIndex: 'code'
							},
							{
								text: IRm$.r1("B_TEXT"),
								flex: 1,
								sortable: false,
								dataIndex: 'text'
							}
						],
						viewConfig: {
							stripeRows: true
						}
					}
				]
			}
		];
		
		IG$.d$ValSel.superclass.initComponent.apply(this);
	},
	
	listeners: {
		afterrender: function() {
			this.init_f();
		}
	}
});


IG$.valueSelectWindow = $s.extend($s.window, {
	modal: true,
	region:'center',
	layout: 'card',
	
	closable: false,
	resizable:false,
	width: 630,
	height: 500,
	
	field: null,
	
	callback: null,
	selmode: 0,
	
	_confirm: function() {
		var me = this,
			seldatas = [],
			i;
		
		if (me.selmode == 0)
		{
			var sgrid = this.down("[name=_2]"),
				selected = sgrid.store.data.items
			
			if (selected && selected.length > 0)
			{
				for (i=0; i < selected.length; i++)
				{
					seldatas.push(selected[i].data);
				}
			}
		}
		else if (me.selmode == 1)
		{
			var sinp = me.down("[name=txtselvalues]"),
				sel = sinp.getValue(),
				selected;
				
			if (sel)
			{
				selected = sel.split(";");
				for (i=0; i < selected.length; i++)
				{
					if (selected[i])
					{
						seldatas.push({
							code: selected[i],
							text: selected[i]
						});
					}
				}
			}
			
		}
		
		this.callback && this.callback.execute(seldatas);
		
		this.close();
	},
	
	swapSelMode: function() {
		var me = this,
			p = me.getLayout(),
			btnSelMode = me.down("[name=btnSelMode]"),
			stext;
		
		if (me.selmode == 0)
		{
			me.selmode = 1;
			stext = IRm$.r1("B_COMBO_VAL");
		}
		else
		{
			me.selmode = 0;
			stext = IRm$.r1("B_CUST_VAL");
		}
		btnSelMode.setText(stext);
		p.setActiveItem(me.selmode);
	},
	
	initComponent : function() {
		var me = this,
			mainpanel = new IG$.d$ValSel({
				sheetoption: me.sheetoption,
				reportoption: me.reportoption,
				meta_type: me.meta_type,
				flex: 1,
				prompt: me.prompt,
				field: me.field,
				initial_values: me.initial_values
			});
		
		this.title = IRm$.r1("T_VALUE_SELECT");
				 
		$s.apply(this, {
			defaults:{
				padding: ig$.padding,
			},
			items: [
				mainpanel,
				{
					xtype: "form",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							xtype: "displayfield",
							value: IRm$.r1("L_CVAL_DESC")
						},
						{
							xtype: "textarea",
							fieldLabel: IRm$.r1("B_VALUES"),
							name: "txtselvalues",
							labelPosition: "top",
							flex: 1
						}
					]
				}
			],
			buttons:[
				'->',
				{
					text: IRm$.r1("B_CUST_VAL"),
					name: "btnSelMode",
					handler: function() {
						var me = this;
						me.swapSelMode();
					},
					scope: this
				},
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			]
		});
		
		IG$.valueSelectWindow.superclass.initComponent.apply(this, arguments);
	}
});

