

/**
 * radiobuttons control
 */
IG$._FC_radiobuttons = $s.extend(IG$._baseFC, {
	objtype: "radiobuttons",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			ui = $("<table class='mec-radiobuttons'><tr><td><ul></ul></td></tr></table>")
				.appendTo(container),
			td = $("td", ui);
			
		td.bind("radioboxchanged", function() {
			me.trigger("change_val");
		});
		
		return ui;
	},
	setValue: function(value, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			i, sctrl1;
			
		if (fitem.data)
		{
			for (i=0; i < fitem.data.length; i++)
			{
				sctrl1 = $("input[type='radio']", fitem.data[i].u2);
				
				if (cmap[fitem.data[i].code])
				{
					sctrl1.attr("checked", "checked");
				}
				else
				{
					sctrl1.removeAttr("checked");
				}
			}
		}
	},
	loadData: function(data) {
		var me = this,
			ui = me.ui,
			fitem = me.fitem,
			td = $("ul", ui),
			inp,
			box;
		
		td.empty();
		
		window.rdo_id = window.rdo_id || 0;
		window.rdo_id++;
		
		dval = me.getDefaultValue(fitem, 0);
		
		$.each(data, function(i, dt) {
			var box = $("<li></li>").appendTo(td),
				inp, inp_b;

			if (me.md)
			{
				window.rdo_lbl_id = window.rdo_lbl_id || 0;
				window.rdo_lbl_id++;
				inp = $("<md-radio id='radio_lb_" + (window.rdo_lbl_id) + "' name='radio_" + (window.rdo_id) + "' value='" + dt.code + "'></md-radio>").appendTo(box);
				$("<label for='radio_lb" + (window.rdo_lbl_id) + "'>" + (dt.disp || dt.code) + "</label>").appendTo(box);
			}
			else
			{
				inp = $("<label><input type='radio' name='radio_" + (window.rdo_id) + "' value='" + dt.code + "'/><span>" + (dt.disp || dt.code) + "</span></label>").appendTo(box)
				inp_b = $("input[type='radio']", inp);
			}
			
			dt.u2 = inp;
			dt.u2b = inp_b;
			
			if ((dval && dt.code == dval) || dt.selected)
			{
				if (me.md)
				{
					inp[0].checked = true;
				}
				else
				{
					inp_b.prop("checked", true);
				}
			}
			
			if (me.md)
			{
				inp[0].addEventListener("change", function() {
					setTimeout(function() {
						td.trigger("radioboxchanged");
					}, 100);
				});
			}
			else
			{
				inp.bind("change", function() {
					setTimeout(function() {
						td.trigger("radioboxchanged");
					}, 100);
				});
			}
		});
		
		td.trigger("radioboxchanged");
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem;
			
		if (fitem.data)
		{
			for (let j=0; j < fitem.data.length; j++)
			{
				if (me.md)
				{
					if (fitem.data[j].u2 && fitem.data[j].u2[0].checked)
					{
						value.push({code: fitem.data[j].code, value: fitem.data[j].value});
					}
				}
				else if (fitem.data[j].u2 && $("input[type='radio']", fitem.data[j].u2).is(':checked'))
				{
					value.push({code: fitem.data[j].code, value: fitem.data[j].value});
				}
			}
		}
	},
	clear: function() {
		var me = this,
			fitem = me.fitem,
			fd = fitem.data;
			
		if (fd && fd.length)
		{
			for (let i=0; i < fd.length; i++)
			{
				if (me.md)
				{
					if (fd[i].u2)
					{
						fd[i].u2[0].checked = false;
					}
				}
				else
				{ 
					fd[i].u2 && fd[i].u2.removeAttr("selected");
				}
			}
		}
		me.trigger("change_val");
	}
});

IG$.$FCinst["radiobuttons"] = new IG$._FC_radiobuttons();