IG$.metaSelectDlg = $s.extend($s.window, {
	
	width: 680,
	height: 550,
	layout: 'fit',
	modal: true,
	mode: 'select',
	xtype: "window",
	
	open_folder_clickhandler: function(node) {
		var me = this,
			typename = node.type.toLowerCase(),
			itemname = node.name,
			itemaddr = node.nodepath,
			itemuid = node.uid || node.address,
			is_sub = node.is_sub,
			bproc = false,
			req = new IG$._rpc$();
		
		if (IG$.testVal("folder|table|inlineview|javapackage|metrics|root|datemetric|dataset", typename) || is_sub || (typename == "bobject" && node.root))
		{
			me.selectedPath = {
				uid: itemuid, 
				nodepath: itemaddr,
				name: itemname
			};
			
			req.init(null, 
				{
					ack: "content",
					payload: {uid: itemuid},
					mbody: {option: "folder"}
				}, me, me.rs_open_folder_clickhandler, null);
			req.send();
			
			bproc = true;
		}
		
		return bproc;
	},
	
	rs_open_folder_clickhandler: function (jdoc) {
		var child = jdoc ? jdoc.children : null;
		
		this.processItemNodes(child, jdoc);
	},
	
	load_content: IG$.load_content,
	
	rload_content: function(jdoc, ltype) {
		var me = this,
			datagrid = me.down("[name=datagrid]"),
			ctype, cname,
			i,
			d,
			dp = [],
			cpath = null,
			cuid,
			v;
			
		me.openItem = null;
		
		me.ltype = ltype;
		
		if (ltype == 0 || ltype == 5 || ltype == 1)
		{
			me.openItem = jdoc;
			cname = me.openItem.name;
			cpath = me.openItem.nodepath;
			cuid = me.openItem.uid;
			ctype = me.openItem.type.toLowerCase();
		}
		
		me.setBreadCrumb(cpath, cuid);
		
		if (jdoc.children)
		{
			for (i=0; i < jdoc.children.length; i++)
			{
				d = jdoc.children[i];
				d.ltype = d.type.toLowerCase();
				d.iconcls = IG$.get_metatype_icon(d.ltype, d);
				dp.push(d);
			}
		}
		
		IG$.sortMeta(dp);
				
		datagrid.store.loadData(dp);
	},
	
	processItemNodes: function(child, item) {
		var itemnodes = [],
			me = this,
			datagrid = me.down("[name=datagrid]"),
			hidden = false,
			i;
			
		me.setBreadCrumb(item.nodepath, item.uid);
		
		if (child)
		{
			for (i=0; i < child.length; i++)
			{
				var obj = child[i];
				obj.itemtype = obj.type || obj.itemtype;
				
				hidden = (me.visibleItems == null || (me.visibleItems 
					&& (me.visibleItems + ';').indexOf((obj.type + ';').toLowerCase()) > -1)) ? false : true;
					
				if (hidden == false)
				{
					itemnodes.push(obj);
				}
			}
		}
		datagrid.store.clearData();

		IG$.sortMeta(itemnodes);
		datagrid.store.loadData(itemnodes);
	},
	
	setBreadCrumb: function(cpath, cuid) {
		var me = this,
			bc = me.down("[name=_bc]"),
			bcbody = bc ? $(bc.body.dom) : null,
			cplist,
			cp = [],
			c,
			i, j,
			ul;
			
		bcbody.empty();
		me.bcuid = cuid,
		me._breadcrumbitems = [];
		
		if (cpath)
		{
			cplist = cpath.split("/");
			for (i=1; i < cplist.length; i++)
			{
				c = {
					name: cplist[i],
					cpath: ""
				};
				
				for (j=1; j < i+1; j++)
				{
					c.cpath += "/" + cplist[j];
				}
				
				cp.push(c);
			}
			
			ul = $("<ul class='ig-navi-breadcrumb'></ul>").appendTo(bcbody);
			
			$.each(cp, function(m, mo) {
				var sp,
					li,
					bl = m < cp.length - 1;
					
				if (m > 0)
				{
					sp = $("<li class='ig-navi-breadcrumb-sep'>&gt;</li>").appendTo(ul);
				}
				
				li = $("<li class='" + (bl ? "qlink" : "") + "'>" + (mo.lname || mo.name) + "</li>").appendTo(ul);
				li.appendTo(ul);
				
				me._breadcrumbitems.push(mo);
				
				if (bl)
				{
					li.bind("click", function() {
						me.load_content(0, mo.cpath);
					});
				}
			});
		}
	},
	
	_confirm: function() {
		var me = this,
			selitem = me.selectedItem,
			datagrid = me.down("[name=datagrid]"),
			sel = datagrid.getSelectionModel().selected,
			i,
			rec;
		
		if (me.mode == 'select')
		{
			if (!selitem && me.targetobj != "folder")
			{
				IG$.alertmsg(ig$.appname, IRm$.r1('L_SELECT_ITEM'), null, me, 1, "error");
				return;
			}
			else if (me.targetobj == "folder")
			{
				if (!me.selectedPath)
				{
					IG$.alertmsg(ig$.appname, IRm$.r1('L_SELECT_ITEM'), null, me, 1, "error");
					return;
				}
				
				selitem = me.selectedPath;
			}
			
			if (me.multiselect)
			{
				selitem = [];
				
				for (i=0; i < sel.length; i++)
				{
					rec = sel.items[i];
					selitem.push(rec.data);
				}
			}
			
			if (me.callback)
			{
				me.callback.execute(selitem);
			}
		}
		else if (me.mode == 'newitem' || me.mode == 'newitem_root')
		{
			var txtinput = me.txtItemName.getValue();
			
			if (txtinput == '')
			{
				IG$.alertmsg(ig$.appname, IRm$.r1('L_TYPE_ITEM_NAME'), null, me, 1, "error");
				return;
			}
			else if (!me.selectedPath)
			{
				IG$.alertmsg(ig$.appname, IRm$.r1('L_SELECT_PATH'), null, me, 1, "error");
				return;
			}
			
			me.selectedPath.name = txtinput;
			
			if (me.callback)
			{
				me.callback.execute(me.selectedPath);
			}
		}
		
		me.close();
	},
	
	custom_expanded_func: function(node) {
		var me = this,
			tree = me.tree;
		
		if (me.mode == "newitem" && node.isRoot() && node.childNodes.length == 0)
		{
			// shows creating folder
			setTimeout(function() {
				IG$.alertmsg(ig$.appname, IRm$.r1("B_SELECT_FOLDER"), null, null, 0, "");
				tree.m_0._createMetaObject(
					"Folder", 
					node.get("uid") || "/", 
					node.get("nodepath") || "/", 
				node);
			}, 1000);
		}
		else if (me.mode == 'newitem_root' && node.isRoot())
		{
			tree.custom_click_func && tree.custom_click_func.execute(node, node.data);
		}
	},
	
	initComponent: function() {
		var me = this,
			tree_options = {
				instance: me.instance,
				showtoolbar: false,
				_search: true,
				custom_click_func: new IG$.callBackObj(me, function(node, data) {
					me.open_folder_clickhandler(data);
				}),
				custom_expanded_func: new IG$.callBackObj(me, me.custom_expanded_func),
				region: "center",
				name: "__mtree",
				flex: 1,
				visibleItems: me.folderItems || 'folder;table;inlineview;dataset;',
				tree_options: me.tree_options
			},
			comp;
		
		me.title = (me.mode == 'newitem' || me.mode == 'newitem_root') ? IRm$.r1('T_META_SAVE') : IRm$.r1('T_META_SELECT');
		
		tree_options.initpath = me.initpath;

		if (me.rootuid)
			tree_options.rootuid = me.rootuid;

		var is_newitem_root = me.mode == 'newitem_root';

		if (is_newitem_root)
			tree_options.hidden = true;
		
		me.tree = new IG$.naviTree(tree_options);
		
		comp = {
			items: [
				{
					xtype: 'container',
					layout: "border",
					padding: 0,
					border: 0,
					items: [
						{
							xtype: 'container',
							width: is_newitem_root ? 10 : 210,
							region: "west",
							split: is_newitem_root ? false : true,
							layout: "fit",
							margins: 0,
							border: 1,
							items: [
								me.tree
							]
						},
						{
							xtype: 'panel',
							region: "center",
							flex: 2,

							border: 1,
							layout: {
								type: 'vbox',
								align: 'stretch'
							},
							
							items: [
								{
									xtype: "panel",
									name: "_bc",
									height: 32,
									border: 0
								},
								{
									xtype: "grid",
									name: "datagrid",
									border: 0,
									store: {
										xtype: "store",
										fields: [
											"name", "lname", "description", "type", "nodepath", "memo", "uid"
										]
									},
									selModel: {
										mode: (me.multiselect) ? "MULTI" : "SINGLE"
									},
									tbar: [
										{
											xtype: "textfield",
											flex: 1,
											emptyText: IRm$.r1("L_SEARCH_KWD"),
											name: "_filter",
											enableKeyEvents: true,
											listeners: {
												keyup: function(tobj, e, eopts) {
													e.keyCode == 13 && IG$._dofilter(this, "datagrid", ["name", "lname", "description"]);
												},
												scope: this
											}
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											handler: function() {
												IG$._dofilter(this, "datagrid", ["name", "lname", "description"]);
											},
											scope: this
										}
									],
									columns: [
										{
											header: IRm$.r1("B_NAME"), 
											dataIndex: 'name', 
											flex: 1,
											renderer: function(value, metadata, record) {
												return record.get("lname") || record.get("name");
											}
										},
										{
											header: IRm$.r1("B_TYPE"), 
											dataIndex: 'type'
										},
										{
											header: IRm$.r1("B_DESC"), 
											dataIndex: 'description'
										}
									],
									stripeRows: true,
									stateful: true,
									stateId: 'grid',
									flex: 1,
									listeners: {
										itemdblclick: function(view, record, item, index, e) {
											var me = this,
												datagrid = me.down("[name=datagrid]"),
												data = datagrid.store.data.items[index].data,
												dtype = data.type.toLowerCase();
											
											if (IG$.testVal("folder|table|inlineview|datemetric|bobject", dtype))
											{
												if (me.targetobj && me.targetobj.indexOf(dtype + ";") > -1)
													return;
												me.open_folder_clickhandler(data);
											}
										},
										itemclick: function(view, record, item, index, e) {
											if (index > -1)
											{
												var me = this,
													datagrid = me.down("[name=datagrid]"),
													data = datagrid.store.data.items[index].data,
													dtype = data.type.toLowerCase(),
													sel = datagrid.getSelectionModel().selected,
													selitem,
													rec, i;
						
												if (/folder|table|inlineview|bobject/.test(dtype) == true && (!me.targetobj || (me.targetobj && me.targetobj.indexOf(dtype + ";") < 0)))
												{
													me.open_folder_clickhandler(data);
												}
												else
												{
													me.selectedItem = data;
													
													if (me.multiselect)
													{
														selitem = [];
														
														for (i=0; i < sel.length; i++)
														{
															rec = sel.items[i];
															selitem.push(rec.get("name"));
														}
														
														me.txtItemName.setValue(selitem.join(","));
													}
													else
													{
														me.txtItemName.setValue(data.name);
													}
												}
											}
										},
										scope: this
									}
								}
							],
							
							bbar: [
								{
									name: "txtItemName",
									fieldLabel: IRm$.r1("B_NAME"),
									xtype: 'textfield',
									enableKeyEvents: true,
									border: 0,
									listeners: {
										'keyup': function(item, e) {
											var me = this;
											if (e.keyCode == 13)
											{
												setTimeout(function() {
													me._confirm();
												}, 10);
											}
										},
										scope: this
									}
								}
							]
						},
						{
							xtype: "container",
							region: "east",
							hidden: is_newitem_root ? false : true,
							width: 10
						}
					]
				}
			],
			buttons: [
				{
					xtype: 'button',
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					xtype: 'button',
					text: IRm$.r1('B_CANCEL'),
					handler: function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(obj, eOpt) {
					var me = obj,
						m_0 = me.tree.down("[name=m_0]");
						
					me.datagrid = me.down("[name=datagrid]");
					me.txtItemName = me.down("[name=txtItemName]");
				}
			}
		};
		
		if (me.cancelable)
		{
			comp.buttons.splice(0, 0, "->");
			comp.buttons.splice(0, 0, {
				xtype: "button",
				text: IRm$.r1("B_CLEAR"),
				handler: function() {
					var me = this;
					
					me.callback && me.callback.execute(null);
					me.close();
				},
				scope: this
			});
		}
		
		$s.apply(me, comp);

		IG$.metaSelectDlg.superclass.initComponent.call(this);
	}
});
