	closeDockNoti: function(docid) {
		var me = this,
			dzone = me.dzone,
			rop = me.reportoption,
			item = dzone.getBox(docid),

			view = (item ? item.view : null),
			i, j, sheets = me.sheets,
			sheets_id = me.sheets_id,
			sheet, r = false;

		me.contentchanged = true;

		if (view)
		{
			if (item.objtype == "FILTER")
			{
				me.onFilterUpdate(view, false, true);
			}
			
			switch (item.objtype)
			{
			case "SHEET":
				$.each(sheets, function(i, sheet) {
					if (sheet == view)
					{
						delete sheets_id[sheet.sheet_id];
						sheets.splice(i, 1);
						if (sheet.sheetoption && sheet.sheetoption.objtype == "SHEET" && rop.sheets.length > i)
						{
							rop.sheets.splice(i, 1);
						}
						r = true;
						return false;
					}
				});
				
				// reindexing sheets
				$.each(sheets, function(i, sheet) {
					sheet.sheetindex = i;
				})
				me.down("[name=tbrescount]").setText("");
				break;
			default:
				if (me.ctrls[docid])
				{
					view.__dx = true;
					delete me.ctrls[docid];
				}
				r = true;
				break;
			}
		}
		else
		{
			if (me.ctrls[docid])
			{
				delete me.ctrls[docid];
			}
			r = true;
		}
		
		return r;
	},

