	showSheetOpt: function(sheetindex, sheetview, cb) {
		sheetview.sheetindex = sheetindex;

		var me = this,
			pop = new IG$.sheetobj({
				instance: me.instance,
				dzone: me.dzone,
				sheets: me.sheets,
				sheetoption: sheetview.sheetoption,
				sheetindex: sheetindex,
				reportoption: me.reportoption,
				callback: new IG$.callBackObj(me, me.rshowSheetOpt, [sheetview, cb])
			});

		IG$.checkLogin(this, pop);
	},

	rshowSheetOpt: function(dlg, opt) {
		var me = this,
			sheetview = opt[0], cb = opt[1],
			sheets = me.reportoption.sheets,
			rop = me.reportoption,
			sop = sheetview.sheetoption,
			dzone = me.dzone,
			docid, sheet, msheetview,
			sheetindex = sheetview.sheetindex,
			ubody, i, nsop,
			rsheets;
		
		cb && cb.execute();
		
		docid = (sop.objtype == "SHEET") ? sop.model.layoutinfo.docid : sop.docid;
		ubody = dzone.getBox(docid);

		if (ubody)
		{
			me.contentchanged = true;
			
			rsheets = rop.sheets;
			
			if (sop.changetype)
			{
				me.activeSheet = 0;
				if (sop.changetype == "SHEET")
				{
					for (i=0; i < rsheets.length; i++)
					{
						if (rsheets[i] == sop)
						{
							rsheets.splice(i, 1);
							break;
						}
					}

					for (i=0; i < me.sheets.length; i++)
					{
						if (me.sheets[i] == sheetview)
						{
							me.sheets.splice(i, 1);
							break;
						}
					}

					for (i=0; i < me.sheets.length; i++)
					{
						me.sheets[i].sheetindex = i;
					}
				}

				if (ubody.view)
				{
					ubody.view.removeObj();
					ubody.box_container.empty();
				}

				if (sop.objtype == "SHEET")
				{
					sheet = new IG$.clReport(null, me.itemtype, false);
					sheet.model.layoutinfo.docid = docid;
					rsheets.push(sheet);
					msheetview = me.createSheet(sheetindex, sheet, ubody);
					ubody.view = msheetview;
					me.sheets.push(msheetview);
					me.sheets_id[msheetview.sheet_id] = msheetview;
					msheetview.sheetindex = me.sheets.length - 1;
				}
				else
				{
					if (sop.changetype == "SHEET")
					{
						nsop = new IG$.sheetfiltercomp(null);
						nsop.objtype = sop.model.objtype;
						nsop.close = sop.model.close;
						nsop.name = sop.model.name;
					}
					me.createCtrl(sop, ubody);
					sheet = ubody.view;

					if (sop.changetype == "SHEET")
					{
						me.ctrls[ubody.docid] = nsop;
					}

					var w = IG$.j$ext._w(sheet.container),
						h = IG$.j$ext._h(sheet.container);
					sheet.setSize(w, h);
				}

				me.updateLayout(false);
			}

			if (sop.objtype == "FILTER" || sop.objtype == "TEXT" || sop.objtype == "NAVI" || sop.objtype == "RPT_VIEW" || sop.objtype == "FB_VIEW" || sop.objtype == "SHEET")
			{
				if (sop.objtype == "TEXT")
				{
					ubody.view.cls_id = null;
				}
				if (sop.objtype == "FILTER")
				{
					ubody.view.validateItems(null, false, false, true);
				}
				else
				{
					ubody.view.validateItems();
				}
			}
			
			dzone.floatWidget(docid);
			
			ubody.setTitle(sop.model.name);
			ubody.showTitle(!sop.model.hidetitle);
			ubody.setPanelCss(sop.model.panel_css);
			
			ubody.fw = sop.fw;
			ubody.fh = sop.fh;

			ubody.setReportOption(sop);

			ubody.validateProperty(1);
		}

		dzone.updateDisplay(true);
	},

