	cacheTbar: function() {
		var me = this,
			tb = me._tbar,
			citems = me._tbaritems,
			_tbarcache = me._tbarcache;

		if (!tb)
			return;

		if (!_tbarcache)
		{
			_tbarcache = me._tbarcache = {};

			for (let i=0; i < citems.length; i++)
			{
				_tbarcache[citems[i]] = tb.down("[name=" + citems[i] + "]");
			}
		}

		return _tbarcache;
	},

	

	updateTbarAll: function() {
		var me = this,
			instance = me.instance,
			tb = me._tbar,
			_tbarcache = me._tbarcache,
			citems = me._tbaritems,
			i, j,
			vitems = [],
			v;

		if (!tb)
			return;

		tb.suspendLayouts();

		_tbarcache = me.cacheTbar();

		for (i=0; i < citems.length; i++)
		{
			_tbarcache[citems[i]].hide();
		}

		if (me.writable || !me.uid)
		{
			vitems.push("t_save");
		}
		
		if (me.writable && me.uid)
		{
			vitems.push("t_share");
			vitems.push("t_userdoc");
			
			// if (ig$.$l_ < 5)
			// {
				vitems.push("t_schedule");
				vitems.push("t_fav");
			// }
		}

		vitems.push("t_save_as");

		vitems.push(["t_run", "t_tool", "t_exp", "t_grid", "t_chart", "t_anal", "t_pivot", "t_r_rptview", "t_r_frmview", "t_r_story"]);

		if (instance.dlgLogin.logininfo.l3.charAt(0) != "P")
		{
			vitems.push("t_r");
			vitems.push("t_python");
			vitems.push("t_fview");
		}

		me.updateTbar();
		me.updateExpOpt();
		
		var activeview = me.activeSheet > -1 ? me.sheets[me.activeSheet] : null;
		
		if (activeview && activeview.sheetoption && activeview.sheetoption.model && activeview.sheetoption.model.viewmode)
		{
			me.updateViewMode(activeview.sheetoption.model.viewmode);
		}
		
		_tbarcache["t_sheet"][ig$.features[_tbarcache["t_sheet"].cls] === false && me.editmode ? "show" : "hide"]();
		me.down("[name=t_exp_opt]").setVisible(ig$.features[_tbarcache["t_exp"].cls] === false && me.editmode); // && ig$.$l_ < 5);

		for (i=0; i < vitems.length; i++)
		{
			if (typeof(vitems[i]) == "string")
			{
				me.chk_tbar(_tbarcache[vitems[i]]);
			}
			else
			{
				for (j=0; j < vitems[i].length; j++)
				{
					me.chk_tbar(_tbarcache[vitems[i][j]]);
				}
			}
		}

		tb.resumeLayouts();
		tb.doLayout();
	},
	
	chk_tbar: function(tbutton) {
		var v,
			cls = tbutton.cls.split(";");
		
		$.each(cls, function(k, c) {
			if (ig$.features[c] === false)
			{
				v = 1;
				
				if (c == "t_fview")
				{
					v = 0;
					if (activeview && activeview.sheetoption && activeview.sheetoption.model && activeview.sheetoption.model.tb_formview)
					{
						v = 1;
					}
				}
			}
			
			if (!v)
				return false;
		});
		
		tbutton[v ? "show" : "hide"]();
	},

	updateTbar: function() {
		var me = this,
			toolbarcache = me.cacheTbar(),
			cube_objects = me.reportoption.cube_objects,
			activeview = me.sheets[me.activeSheet],
			reportmode;

		toolbarcache["t_sql_view"].hide();
		
		if (me.meta_type == "sql_report")
		{
			toolbarcache["t_sql_view"].show();
		}
		else if (ig$.features[toolbarcache["t_sql_view"].cls] !== false)
		{
			toolbarcache["t_sql_view"].show();
		}
	},

	updatePromptTbar: function(reloadprompt) {
		var me = this,
			sop = null,
			prompts,
			ctrl = me.down("[name=toolbarprompt]"),
			activeview = me.sheets[me.activeSheet];

		if (ctrl)
		{
			ctrl.hide();
		}

		if (ctrl && activeview && me.reportoption && me.reportoption.sheets.length > me.activeSheet)
		{
			sop = me.reportoption.sheets[me.activeSheet];
			prompts = sop.needPrompt();

			if (prompts && prompts.length > 0)
			{
				ctrl.show();

				if (reloadprompt)
				{
					activeview.promptpanel && activeview.promptpanel.show();
					activeview.showPrompt(prompts);
				}
			}
			else if (reloadprompt)
			{
				activeview.promptpanel && activeview.promptpanel.hide();
			}
		}
	},

