	addSheet: function(dlg) {
		var me = this,
			sheet = dlg.sheetoption,
			model = sheet.model,
			dzone = me.dzone,
			sheetindex = me.sheets.length,
			ubody, sop,
			docid,
			i;
		
		sheet.objtype = model.objtype = dlg.objtype;
		// model.drillreport = dlg.drillreport;
		// model.drilltarget = dlg.drilltarget;
		model.close = dlg.closable;
		// model.name = dlg.name;

		switch (dlg.objtype)
		{
		case "SHEET":
			me.reportoption.sheets.push(sheet);
			// ubody = me.createCtrl(sheet);
			// sheet.layoutinfo.docid = ubody.docid;
			break;
		default:
			ubody = me.createCtrl(sheet);
			me.ctrls[ubody.docid] = sheet;
			model.docid = ubody.docid;
			ubody.setReportOption(sheet);
			break;
		}
		
		if (dlg.objtype == "RPT_VIEW")
		{
			IG$.ShowWarning(IRm$.r1("M_PIVOT_CHANGED"), me, "info");
		}

		me.updateLayout(false);
		dzone.updateDisplay(true);
		
		docid = (sheet.objtype == "SHEET") ? sheet.model.layoutinfo.docid : sheet.docid;
		ubody = dzone.getBox(docid);
		
		if (ubody)
		{
			ubody.setTitle(sheet.model.name);
			ubody.showTitle(!sheet.model.hidetitle);
			ubody.fw = sheet.model.fixed_width;
			ubody.fh = sheet.model.fixed_height;
			
			ubody.setReportOption(sheet);
			ubody.validateProperty();
		}
	},

