	/** 
	 * save reoprt content
	 * @param uid {string} unique identifier
	 * @param pivot {object} pivot view model
	 * @param afterclose {boolean} close window after save 
	 */
	saveContent: function(uid, pivot, afterclose) {
		var me = this,
			req = new IG$._rpc$();
		req.init(me,
			{
				ack: "writecontent",
				payload: {uid: uid},
				mbody: pivot,
				meta_type: me.meta_type || "report",
			}, me, me.rsaveContent, null, [afterclose]);
		req.send();
	},

	rsaveContent: function(jdoc, opt) {
		var me = this,
			afterclose = (opt ? opt[0] : false);
		if (afterclose)
		{
			me.ignoreclose = true;
			me.close();
		}
		else
		{
			me.contentchanged = false;
			me.id = jdoc.type.toLowerCase() + "_" + jdoc.uid;
			me.down("[name=tbreportname]").setText(jdoc.name);
			
			IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVED"), null, null, 0, "success");

			me.fireEvent("main_widget_saved");
		}
		
		if (ig$.report_screenshot !== false) //  && ig$.$l_ < 5)
		{
			me._capture_frame();
		}
	},

