/**
 * @module widget/rfTabPanel
 * @desc Report TabPanel Control
 *
 */
IG$.rfTabPanel = function (instance, container, sop, owner) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	me.owner = owner;
	
	if (me.owner && me.owner.box)
	{
		me.owner.box.bind("updatecomplete", function() {
			me.validateItems();
		});
	}
	
	me.updateValues = true;
	me.active = null;
	me.$init();
};

IG$.rfTabPanel.prototype = {
	$init: function() {
		var me = this,
			values = {},
			browser, i,
			owner = me.owner,
			ctrls = me.owner ? me.owner.ctrls : null,
			ctrl, n=0;
		
		me.buttons = [];
		me.contentarea = $("<div></div>").appendTo(me.container);
		me.tabarea = $("<div class='idv-dtab-area'></div>").appendTo(me.contentarea).hide();
		me.tabul = me.tabarea; // $("<ul></ul>").appendTo(me.tabarea);
		
		me.validateItems();
	},
	
	removeObj: function() {
	},
	
	tabHeight: function() {
		var me = this;
		
		return me.tabarea.outerHeight() - 3;
	},
	
	validateItems: function() {
		var me = this,
			owner = me.owner,
			dobj = (owner && owner.docitems && me.sheetoption ? owner.docitems[me.sheetoption.docid] : null),
			n=0,
			bf = false,
			i,
			pactive,
			tv = me.sheetoption && me.sheetoption.tab_option ? (me.sheetoption.tab_option.showtab == "F" ? false : true) : true;
		
		me.tabarea[tv || me.editmode ? "show" : "hide"]();
		me.tabul.empty();
		
		me.buttons = [];
		
		if (dobj && dobj.children && dobj.children.length > 0)
		{
			pactive = dobj.active;
			
			if (dobj.active)
			{
				for (i=0; i < dobj.children.length; i++)
				{
					if (dobj.children[i].docid == dobj.active)
					{
						bf = true;
						break;
					}
				}
				
				dobj.active = (bf == false) ? null : dobj.active;
			}
			
			$.each(dobj.children, function(i, item) {
				if (item.docid)
				{
					var di = owner.bodylist[item.docid],
						btn = $("<div class='ig-dtab-item'><span class='ig-tab-tt'>" + (di.title || "Tab " + i) + "</span></div>").appendTo(me.tabul);
					if ((dobj.active && dobj.active == item.docid) || (!dobj.active && n == 0))
					{
						btn.addClass("selected");
						dobj.active = item.docid;
					}
					
					btn.docid = item.docid;
					
					btn.bind("click", function() {
						me.setActiveDoc(item.docid);
					});
					
					me.buttons.push(btn);
					
					n++;
				}
			});
			
			if (pactive != dobj.active && dobj.active)
			{
				me.setActiveDoc(dobj.active, true);
			}
		}
	},
	
	/**
	 * set selected tab
     * @memberof module:widget/rfTabPanel
	 * @param {string} docid - document identifier
	 * @param {boolean} bsuspend_run - suspend runnig sheet again.
	 */
	setActiveDoc: function(docid, bsuspend_run) {
		var me = this,
			buttons = me.buttons,
			owner = me.owner,
			dobj = (owner && owner.docitems && me.sheetoption ? owner.docitems[me.sheetoption.docid] : null),
			btn,
			pdocid = me.sheetoption.docid,
			mview,
			i,
			mc;
		
		for (i=0; i < buttons.length; i++)
		{
			btn = buttons[i];
			if (btn.docid == docid)
			{
				btn.addClass("selected");
			}
			else
			{
				btn.removeClass("selected");
			}
		}
		
		if (dobj)
		{
			dobj.active = docid;
			
			for (i=0; i < dobj.children.length; i++)
			{
				mc = owner.docitems[dobj.children[i].docid];
				
				me.setVisible(mc, mc.docid == docid, bsuspend_run);
			}
		}
	},
	
	/**
	 * set visiblility of tab
	 *
     * @memberof module:widget/rfTabPanel
	 * @param {string} ditem - item to set visiblity
	 * @param {boolean} visible - true / false for visibility control
	 * @param {boolean} suspend_run - suspend running report after visible changes
	 */
	setVisible: function(ditem, visible, bsuspend_run) {
		var me = this,
			i,
			mc = ditem.lt.ubody,
			payload;
		
		if (!mc)
		{
			return;
		}
		
		if (ditem._SP && ditem._SP.length)
		{
			for (i=0; i < ditem._SP.length; i++)
			{
				ditem._SP[i].setV(visible);
			}
		}
		
		if (visible)
		{
			mc.visible = true;
			mc.show();
			
			if (mc.view && mc.objtype == "RPT_VIEW" && !mc.view.validated)
			{
				mc.view.validateItems();
			}
			
			mc.objtype == "RPT_VIEW" && mc.view && mc.view.executeItem();
			
			mc.box_title.trigger("click");
			mc.resizeH();
			
			if (mc.view && mc.view.btabrun == true)
			{
				if (bsuspend_run || !mc.view.sheetoption) // || (mc.view.sheetoption)) //  &&  !mc.view.sheetoption.openload))
				{
				}
				else
				{
					mc.view.f_run = false;
					delete mc.view.btabrun;
					payload = mc.view.procRunReport(null);
				}
			}
		}
		else
		{
			mc.visible = false;
			mc.hide();
		}
		
		if (ditem.children)
		{
			for (i=0; i < ditem.children.length; i++)
			{
				me.setVisible(ditem.children[i], visible, bsuspend_run);
			}
		}

		if (payload)
		{
			mc.view.reportpanel._exec_rpt(mc.view.reportpanel, [{
				view: mc.view,
				req: payload
			}]);
		}
	},
	
	setSize: function(w, h) {
		var me = this,
			c = me.contentarea;
		
		IG$.j$ext._w(c, w);
		IG$.j$ext._h(c, h);
	},
	
	updateFilterContent: function(finfo) {
	}
};
