IG$.makeItem = $s.extend($s.window, {
	
	modal: true,
	layout: "fit",
	closable: false,
	resizable:false,
	width: 300,
	autoHeight: true,

	viewmode: "newitem",
	
	_init: function() {
		var me = this,
			t1 = me.itemtype.split(";");
			
		if (t1.length > 1)
		{
			me.itemtype = t1[0];
			me._itemtypes = t1;
			
			var txttitle = me.down("[name=txttitle]"),
				txtedittitle = me.down("[name=txtedittitle]"),
				selitemtype = me.down("[name=selitemtype]"),
				dp = [],
				i;
				
			txttitle.setVisible(false);
			txtedittitle.setVisible(false);
			selitemtype.setVisible(true);
			dp.push({
				name: IRm$.r1("L_CR_TP_SEL"),
				value: ""
			});
			for (i=0; i < t1.length; i++)
			{
				dp.push({
					name: IRm$.r1("D_" + t1[i].toUpperCase()),
					value: t1[i]
				});
			}
			
			selitemtype.store.loadData(dp);
			selitemtype.setValue("");
		}
		
		me.down("[name=fitemname]").focus();
	},
	
	commit_f: function(){
		var me = this,
			citemname = me.down("[name=fitemname]"),
			itemname = me.down("[name=fitemname]").getValue(),
			desc = me.down("[name=fdesc]").getValue(),
			fhelpuid = me.down("[name=fhelpuid]").getValue() || null,
			selitemtype = me.down("[name=selitemtype]"),
			group_dim_name = me.down("[name=group_dim_name]"),
			groupid = me.down("[name=groupid]").getValue();
			
		citemname.clearInvalid();
		
		if (!itemname)
		{
			citemname.markInvalid([citemname.blankText]);
			me._proc = 0;
			return;
		}
		
		if (me.itemtype == "Help" && !fhelpuid)
		{
			me._proc = 0;
			return;
		}
		
		if (me._itemtypes && me._itemtypes.length > 1)
		{
			me.itemtype = selitemtype.getValue();
			
			if (!me.itemtype)
			{
				me._proc = 0;
				return;
			}
		}
		
		if (me.itemtype == "MeasureGroup" && !group_dim_name.getValue())
		{
			group_dim_name.markInvalid([group_dim_name.blankText]);
			me._proc = 0;
			return;
		}
		
		if (me.doUpdate == false)
		{
			if (me.callback)
			{
				me.callback.execute();
			}
			me._proc = 0;
			return;
		}
		
		var req = new IG$._rpc$(),
			purpose = "writecontent",
			address = {
				address: (me.parentnodepath ? (me.parentnodepath == "/") ? me.parentnodepath + itemname 
						: (me.parentnodepath + "/" + itemname) : null),
				name: itemname,
				type: me.itemtype,
				pid: (me.parentuid == "/") ? "" : me.parentuid,
				memo: fhelpuid || null,
				dimname: group_dim_name.getValue(),
				description: desc
			},
			content = {name: itemname};
		
		if (me.itemtype == "Group")
		{
			purpose = "usercontent";
			address = {address: "/usergroup/" + itemname, action: "create", pid: me.parentuid, description: desc, groupid: groupid};
			content = {type: "usergroup", pid: me.parentuid, description: desc, groupid: groupid};
		}
		else if (me.itemtype == "Auth")
		{
			purpose = "usercontent";
			address = {address: "/Auth/" + itemname, action: "create", pid: me.parentuid, description: desc};
			content = {option: "create", name: itemname, description: desc};
		}
		else if (me.itemtype == "tenant")
		{
			purpose = "usercontent";
			address = {address: "/tenants/" + itemname, action: "create", pid: me.parentuid, description: desc};
			content = {};
		}
		
		req.init(me, {
			ack: purpose,
			payload: address,
			mbody: content,
			meta_type: me.meta_type || null
		}, me, me.rs_processMakeMetaItem, function() {
			me._proc = 0;
		});
		req.send();
	},
	
	rs_processMakeMetaItem: function (jdoc) {
		var panel = this;

		if (panel.callback)
		{
			panel.callback.execute(jdoc);
		}
		
		panel.close();
	},
	
	setGroupActive: function(status) {
		var me = this,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "usercontent",
				payload: {address: "/usergroup", action: status},
				mbody: {
					gid: me.uid
				}
			}, me, me.rs_setGroupActive, false, [status]);
		req.send();
	},
	
	rs_setGroupActive: function(jdoc, param) {
		var me = this,
			status = param[0],
			p_grp_desc = me.down("[name=p_grp_desc]"),
			btn_erase = me.down("[name=btn_erase]");
		
		switch (status)
		{
		case "activate":
			p_grp_desc.setValue("Active");
			me.group_active = status;
			btn_erase.setVisible(false);
			break;
		case "delete":
			p_grp_desc.setValue("Blocked");
			me.group_active = status;
			btn_erase.setVisible(true);
			me.down("[name=btn_erase]").show();
			break;
		case "erase":
			me.callback && me.callback.execute();
			me.close();
			break;
		}
	},
	
	initComponent : function() {
		var me = this;

		me.title = me.title || IRm$.r1('L_MAKEITEM_G');

		var itemtypedesc = IRm$.r1("D_" + me.itemtype.toUpperCase());
		
		$s.apply(this, {
			items: [
				{
					xtype: "container",
					padding: ig$.padding,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: 
					[
						{
							xtype: "displayfield",
							value: IRm$.r1('L_MAKEITEM', itemtypedesc),
							name: "txttitle",
							hidden: (me.viewmode != "newitem"),
							height: 30,
							border: 0
						},
						{
							xtype: "displayfield",
							value : IRm$.r1('L_RENAME_ITEM', IG$._gitemname(me.itemname || "")),
							name: "txtedittitle",
							height: 30,
							hidden: (me.viewmode != "edititem"),
							border: 0
						},
						{
							xtype: "panel",
							layout: 'anchor',
							border: 0,
							defaults: {
								anchor: '100%',
								labelWidth: 80
							},
							items: [
								{
									name: "selitemtype",
									hidden: true,
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_CR_TP_SEL"),
									queryMode: 'local',
									displayField: 'name',
									valueField: 'value',
									editable: false,
									autoSelect: true,
									store: {
										xtype: 'store',
										fields: [
											"name", "value"
										]
									}
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1('L_ITEMNAME'),
									name: 'fitemname',
									_fasl: 1,
									allowBlank: true,
									blankText: IRm$.r1("B_REQ"),
									enableKeyEvents: true,
									listeners: {
										'keyup': function(item, e) {
											if (e.keyCode == 13)
											{
												this.commit_f();
											}
										},
										scope: this
									}
								},
								{
									xtype: "textfield",
									fieldLabel: "HELPID",
									name: 'fhelpuid',
									hidden: (me.itemtype == "Help") ? false : true,
									allowBlank: false,
									blankText: IRm$.r1("B_REQ")
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_GROUP_ID"),
									name: "groupid",
									hidden: (me.itemtype == "Group") ? false : true,
									allowBlank: true
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_DIMENSION"),
									name: "group_dim_name",
									blankText: IRm$.r1("B_REQ"),
									hidden: (me.itemtype == "MeasureGroup") ? false : true
								},
								{
									fieldLabel: IRm$.r1('B_DESC'),
									xtype: 'textarea',
									height: 50,
									name: 'fdesc'
								},
								{
									xtype: "fieldset",
									title: IRm$.r1("L_ENABLE_DISABLE"), // "Enable/Disable",
									name: "p_activate",
									hidden: me.itemtype == "Group" && me.uid ? false : true,
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "displayfield",
											name: "p_grp_desc",
											value: me.group_active == 1 ? "Active" : "Deactive"
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "button",
													iconCls: 'icon-toolbar-activate',
													flex: 1,
													text: IRm$.r1("L_ACTIVATE"),
													handler: function() {
														this.setGroupActive("activate");
													},
													scope: me
												},
												{
													xtype: "container",
													width: 10
												},
												{
													xtype: "button",
													iconCls: 'icon-toolbar-deprivation',
													flex: 1,
													text: IRm$.r1("L_DEPRIVATE"),
													handler: function() {
														this.setGroupActive("delete");
													},
													scope: me
												}
											]
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1("L_ERASE_GROUP"),
					name: "btn_erase",
					hidden: me.itemtype == "Group" && me.uid && me.group_active == 0 ? false : true,
					handler: function() {
						this.setGroupActive("erase");
					},
					scope: me
				},
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						var me = this;
						if (!me._proc)
						{
							me._proc = 1;
							me.commit_f();
						}
						else
						{
							IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVE_PROGRESS"), null, null, 0, "warning");
						}
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(tobj) {
					tobj._init();
				}
			}
		});
		
		IG$.makeItem.superclass.initComponent.apply(this, arguments);
	}
});

IG$.makeItemEditor = $s.extend(IG$.makeItem, {
	
	viewmode: "edititem",
	
	commit_f: function() {
		var me = this,
			panel = this,
			fitemname = this.down('[name=fitemname]'),
			itemname = fitemname.getValue(),
			desc = this.down('[name=fdesc]').getValue(),
			fhelpuid = this.down('[name=fhelpuid]').getValue(),
			selitemtype = this.down("[name=selitemtype]"),
			ack = "writecontent",
			address,
			req,
			groupid = this.down("[name=groupid]").getValue(),
			opt = "rename";
		
		if (me._itemtypes && me._itemtypes.length > 1)
		{
			selitemtype.clearInvalid();
			me.itemtype = selitemtype.getValue();
			
			if (!me.itemtype)
			{
				selitemtype.markInvalid(IG$._markInvalid);
				me._proc = 0;
				return;
			}
		}
		
		fitemname.clearInvalid();
		if (!itemname)
		{
			fitemname.markInvalid(IG$._markInvalid);
			me._proc = 0;
			return;
		}
		
		address = {
			uid: me.uid, 
			name: itemname, 
			itemtype: me.itemtype, 
			pid: me.parentuid, 
			description: desc,
			memo: (me.itemtype == "Help") ? fhelpuid : null
		 };
			 
	   switch(me.itemtype)
	   {
	   case "Group":
		   ack = "usercontent";
		   opt = "update";
		   address = {address: "/usergroup/" + itemname, action: "update", gid: me.uid, description: desc, groupid: groupid};
		   break;
	   }
		
		req = new IG$._rpc$();
		req.init(panel, 
			{
				ack: ack,
				payload: address,
				mbody: {option: opt}
			}, panel, panel.rs_processMakeMetaItem, function() {
				me._proc = 0;
			});
		req.send();
	},
	
	initComponent: function() {
		var me = this;

		me.title = IRm$.r1('T_RENAME_ITEM', me.itemname);

		me.on("afterrender", function() {
			var me = this,
				fitemname = me.down('[name=fitemname]'),
				fdesc = me.down('[name=fdesc]'),
				fhelpuid = me.down('[name=fhelpuid]'),
				txttitle = me.down("[name=txttitle]"),
				txtedittitle = me.down("[name=txtedittitle]"),
				groupid = me.down("[name=groupid]");
				
			txttitle.setVisible(false);
			txtedittitle.setVisible(true);

			fitemname.setValue(me.itemname);
			fdesc.setValue(me.description);
			fhelpuid.setValue(me.memo);
			groupid.setValue(me.groupid);
			
			fitemname.focus();

		}, me);
		
		IG$.makeItemEditor.superclass.initComponent.apply(me, arguments);
	}
});

