IG$.cVis.treemap = $s.extend(IG$.cVis.protovis, {
	subtype: "treemap",
	ti: 0,
	updatedisplay: function(w, h) {
		var me = this,
			treemap = me.treemap;
			
		if (treemap && treemap.map)
		{
			// treemap.position.call(treemap, treemap.data.dom, 0, treemap.ti, w, h - treemap.ty);
			// treemap.layout.call(treemap, treemap.data, me.ti, w, h - treemap.ty);
			treemap.box.css({
				top: treemap.ty,
				left: 0,
				width: w,
				height: h - treemap.ty
			});
			
			if (window.echarts)
			{
				treemap.map.resize.call(treemap.map, {width: w, height: h - treemap.ty});
			}
			else
			{
				treemap.map.setSize(w, h - treemap.ty);
				treemap.map.renderTo && $(treemap.map.renderTo).hide().show(0);
			}
		}
	},
	getExportData: function(pobj, callback) {
		if (me.treemap && me.treemap.map)
		{
			if (me.treemap.map.getSVG)
			{
				svg = me.treemap.map.getSVG.call(me.treemap.map);
				pobj.image_type = "svg";
				pobj.image_data = Base64.encode(svg);
			}
			else
			{
				me.getEchartData(me.treemap.map, pobj);
			}
		}
		callback.execute(pobj);
	}
});