	updateSel: function(filters, cols, box) {
		var me = this,
			fs = filters,
			cs = cols,
			bx = box;
		if (me._timerUpdSel)
		{
			clearTimeout(me._timerUpdSel);
		}

		me._timerUpdSel = setTimeout(function() {
			me.aupdateSel(fs, cs, bx);
		}, 800);
	},

	aupdateSel: function(filters, cols, box) {
		var me = this,
			mresult = me.mresult,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			i, j, n,
			sel = [], fname, filter, v, col, val,
			scontainer = me.scontainer,
			p1, p2;

		if (filters)
		{
			for (i=fr; i < data.length; i++)
			{
				// filter names
				v = true;
				for (j=0; j < cols.length; j++)
				{
					fname = cols[j];
					filter = filters[fname];

					if (filter && isNaN(filter.min) == false && isNaN(filter.max) == false)
					{
						col = j + fc;
						val = data[i][col].code;
						val = (val != "") ? Number(val) : 0;
						if (val < filter.min || val > filter.max)
						{
							v = false;
							break;
						}
					}
				}

				if (v)
				{
					sel.push(i);
				}
			}
		}
		else if (box && cols)
		{
			for (i=0; i < cols.length; i++)
			{
				if (cols[i] == box.px)
				{
					px = i+fc;
				}
				else if (cols[i] == box.py)
				{
					py = i+fc;
				}
			}

			for (i=fr; i < data.length; i++)
			{
				v = true;
				p1 = data[i][px].code;
				p2 = data[i][py].code;
				p1 = (p1 != "") ? Number(p1) : 0;
				p2 = (p2 != "") ? Number(p2) : 0;
				p1 = (isNaN(p1) ? 0 : p1);
				p2 = (isNaN(p2) ? 0 : p2);

				if (p1 < box.x1 || p1 > box.x2 || p2 < box.y1 || p2 > box.y2)
				{
					v = false;
				}

				if (v)
				{
					sel.push(i);
				}
			}
		}

		// update table
		var sbox = me.sbox,
			tb = $("<table></table>"),
			th;

		sbox.empty();
		$("<span>" + (sel.length) + " / " + data.length + " Items selected</span>&nbsp;&nbsp;&nbsp;&nbsp;<br><br>").appendTo(sbox);
		var clipbutton = $("<div class='clipbutton'>Select All</div>").appendTo(sbox);
		clipbutton.bind("click", function() {
			IG$.selectAll(tb);
		});
		tb.appendTo(sbox);

		for (i=0; i < fr; i++)
		{
			th = $("<tr></tr>").appendTo(tb);

			for (j=0; j < tc; j++)
			{
				th.append($("<th>" + data[i][j].text + "</th>"));
			}
		}

		for (i=0; i < sel.length; i++)
		{
			th = $("<tr></tr>").appendTo(tb);
			n = sel[i];
			for (j=0; j < tc; j++)
			{
				th.append($("<td>" + data[n][j].text + "</td>"));
			}
		}

		tb.bind("selectstart", function() {
			return true;
		});
	},


	disposeContent: function(ui) {
		var me = this;
		$(".i-sschart-cnt", ui.container).empty();		
		me.$cvis && me.$cvis.dispose();
	},

	loadCustomChart: function(cobj, callback, params) {
		var me = this,
			req = new IG$._rpc$();

		req.init(me, 
			{
				ack: "content",
				payload: {address: cobj.uid},
				mbody: {}
			}, me, function(jdoc) {
				cobj._loaded = true;
				var chart = jdoc.content,
					cscript;

				cscript = IG$.cdsgn_tmpl(chart);

				try
				{
					var dyn = new IG$.cDynScript("custom_chart_" + chart.subtype, 0);
					dyn.loadScript(cscript);
				}
				catch (e)
				{
					void 0;
				}

				callback.execute.apply(callback, params);
				
			}, null);
		req.send();
	},
	
	drawChartResult: function (w, h, isthumb, ispageview) {
		var cret = null,
			me = this,
			mresult = me.mresult,
			cop,
			cinfo,
			ps = false,
			bdatas,
			i;

		me.pw = (w > 0 ? w : me.pw);
		me.ph = (h > 0 ? h : me.ph);

		me._unitcontainer.hide();

		if (mresult)
		{
			if (ispageview == false)
			{
				if (mresult.pagestart > 0 && me.scrollX == 0)
				{
					isthumb = true;
					ps = true;
					var mcr = me.sheetoption.model.chart_option,
						maxchartresult = mcr.maxchartresult,
						tabledata = mresult._tabledata;

					bdatas = Math.min(tabledata.length, (maxchartresult > 0 ? maxchartresult : tabledata.length));
					me.sh = bdatas / mresult.rowcnt;
					me.scrollX = (mresult.pagestart + 20) * w / mresult.rowcnt;
				}
			}

			if (!isthumb && mresult.pagestart == 0)
			{
				me.sh = 1;
				me.scrollX = 0;
			}

			cop = me.cop = me.sheetoption.model.chart_option;
			cop.settings = cop.settings || {};
			cop.charttype = cop.charttype || "cartesian";
			cop.subtype = cop.subtype || "column";
			me.rct = cop.charttype;
			me.rcs = cop.subtype;
			useformula = cop.useformula;
			timeseriesfield = cop.timeseriesfield;

			if (cop.cunittext)
			{
				me._unitcontainer.empty();
				me._unitcontainer.append("<span>" + cop.cunittext + "</span>");
				me._unitcontainer.show();
			}

			me.setFltInfo(mresult.filterdesc || "");

			if (me.drilldepth > 0 && cop.drillcharttype && cop.drillcharttype.length > me.drilldepth && cop.drillcharttype[me.drilldepth])
			{
				for (i=0; i < IG$.chartTypeMenu.length; i++)
				{
					if (IG$.chartTypeMenu[i].subtype == cop.drillcharttype[me.drilldepth])
					{
						cinfo = IG$.chartTypeMenu[i];
						break;
					}
				}
				
				if (cinfo)
				{
					me.rct = cinfo.charttype;
					me.rcs = cinfo.subtype;
				}
			}

			var cls = IG$.cVis[cop.subtype]; 

			if (!cls && ig$.custom_charts[cop.subtype] && !ig$.custom_charts[cop.subtype]._loaded)
			{
				me.loadCustomChart(ig$.custom_charts[cop.subtype], new IG$.callBackObj(me, me.drawChartResult), [w, h, isthumb, ispageview]);
				return;
			}
			
			if (cls)
			{
				try
				{
				var clsview,
						reuse_chart;

					if (me.$cvis && me.$cvis.subtype == cop.subtype) 
					{
						if (me.$cvis.invalidateData)
						{
							reuse_chart = me.$cvis.invalidateData(mresult);

							if (reuse_chart === true)
							{
								clsview = me.$cvis;
							}
						}

						if (!clsview)
						{
							me.disposeContent(me);
						}
					}
					else
					{
						me.disposeContent(me);
					}

					if (!clsview)
					{
						clsview = new cls({
							subtype: cop.subtype,
							rpc: me.rpc,
							chartview: me,
							sheetoption: me.sheetoption,
							chart_option: me.cop,
							container: me.container,
							width: w,
							height: h,
							isthumb: isthumb
						});
						clsview.initComponent();
					}
					clsview.$mresult = mresult;
					clsview.draw(mresult);

					me.$cvis = clsview;
				}
				catch (e)
				{
					setTimeout(function() {
						void 0;
						IG$.ShowError(IRm$.r1("E_CHART_DRAWING") + e.message); // "Error on chart drawing : " + e.message);
					}, 100);
				}
				}
			else
			{
				me.disposeContent(me);
			}
			
			if (!isthumb || ps == true)
			{
				if (me.sh < 1)
				{
					tstyle = {left: 0};
					tstyle.width = w;
					
					me.reghscroll.show();
					me.thumbhwidth = IG$.j$ext._w(me.hscroll); //  * me.sh;
					thumbcalc = Math.max(30, me.thumbhwidth * me.sh);
					me.thumbcalc = thumbcalc;
					me.reghscrollthumb.css({left: Math.min(me.scrollX, me.thumbhwidth - thumbcalc), width: thumbcalc});
					
					me.reghscroll.css(tstyle);
					me.regh = true;
				}
				else
				{
					me.regh = false;
					me.reghscroll.hide();
				}
			}
		}

		return cret;
	},

	area: function(pts) {
	   var area=0;
	   var nPts = pts.length;
	   var j=nPts-1;
	   var p1; var p2;

	   for (var i=0;i<nPts;j=i++) {
		  p1=pts[i]; p2=pts[j];
		  area+=p1.lng*p2.lat;
		  area-=p1.lat*p2.lng;
	   }
	   area/=2;
	   return area;
	},

	

