	getDashStyle: function(n) {
		if (n == "dashed")
			return "Dash";
		else if (n == "dotted")
			return "ShortDot";
		
		return null;
	},
	
	interpolate: function(v, c) {
		var nc = null,
			r, g, b,
			a;
		
		if (c && c.charAt(0) == "#")
		{
			r = c.substring(1, 3);
			g = c.substring(3, 5);
			b = c.substring(5, 7);
			
			r = parseInt(r, 16);
			g = parseInt(g, 16);
			b = parseInt(b, 16);
			
			a = (v / 255) * 0.75 + 0.25;
			
			nc = "rgba(" + r + "," + g + "," + b + "," + a + ")";
		}
		
		return nc;
	},
	
	procClickEvent: function(sender, param, dragselect) {
		var me = this;
		
		me._p1a && clearTimeout(me._p1a);
		
		me._p1a = setTimeout(function() {
			me.procClickHandler(sender, param, dragselect);
		}, 250);
	},

	procClickHandler: function(sender, param, dragselect) {
		if (sender)
		{
			var me = this,
				seriesnames = [],
				categnames = [],
				datarows = [],
				seriesname,
				categname,
				eventowner,
				mcr = me.sheetoption.model.chart_option,
				sep = mcr.xaxissep || ig$.chart_separator || IG$._separator,
				mresult = this.mresult,
				cname,
				swapaxis = mcr.swapaxis,
				c = -1, r = -1, m,
				hidden_columns = {},
				_p,
				t;
				
			sep = sep == "nl" ? "\n" : sep;
				
			if (!param && (!me.selectedData || (me.selectedData && !me.selectedData.length)))
			{
				return;
			}
			
			me.selectedData = [];
			me.rpc._unselect = sender.unselect;
			
			if (sender.amplix_selected && sender.amplix_selected.length)
			{
				me.selectedData.push(...sender.amplix_selected);
			}
			else if (me.cop.charttype == "scatter" || me.cop.charttype == "bubble")
			{
				if (param && param.length)
				{
					for (m=0; m < param.length; m++)
					{
						_p = param[m];
						if (_p.datarow > -1)
						{
							datarows.push(_p.datarow);
						}
					}
				}
				else if (param)
				{
					if (param.datarow > -1)
					{
						datarows.push(param.datarow);
					}
				}
			}
			else
			{
				if (param && param.length)
				{
					for (m=0; m < param.length; m++)
					{
						_p = param[m];
						seriesnames.push(_p.series ? _p.series.name : _p.name);
						if (_p.drname)
						{
							categnames.push(_p.drname);
						}
						else
						{
							categnames.push(_p.category || _p.name || "");
						}
					}
				}
				else if (param)
				{
					seriesnames.push(sender.series ? sender.series.name : sender.name);
					categnames.push(param.point ? param.point.drname || param.point.category || param.point.name : "");
				}
			}
			
			param && param.point && param.point.select && param.point.select(true, false);
			
			if (me.selectedData.length)
			{
				
			}
			else if (datarows.length)
			{
				for (m=0; m < datarows.length; m++)
				{
					r = datarows[m];
					c = mresult.colfix - 1;
					
					if (r > -1 && c > -1)
					{
						mresult._tabledata[r][c].r = r;
						mresult._tabledata[r][c].c = c;
						this.selectedData.push(mresult._tabledata[r][c]);
					}
				}
			}
			else
			{
				if (mresult.hidden_columns) 
				{
					for (m=0; m < mresult.hidden_columns.length; m++) 
					{
						hidden_columns[mresult.hidden_columns[m]] = 1;
					}
				}
				for (m=0; m < seriesnames.length; m++)
				{
					seriesname = seriesnames[m];
					categname = categnames[m];
					
					if (swapaxis == true)
					{
						for (let i=mresult.colfix; i < mresult._tabledata[0].length; i++)
						{
							cname = "";
		
							for (let j=0; j < mresult.rowfix; j++)
							{
								cname += (mresult._tabledata[j][i].text || " ") + sep;
							}
		
							if (cname == categname + sep)
							{
								c = i;
								break;
							}
						}
		
						if (seriesname)
						{
							seriesname = IG$.replaceAll(seriesname, "&#x2f;", "/");
							
							for (let i=mresult.rowfix; i < mresult._tabledata.length; i++)
							{
								cname = "";
		
								for (let j=0; j < mresult.colfix; j++)
								{
									cname += (mresult._tabledata[i][j].text || " ") + sep;
								}
		
								if (cname == seriesname + sep)
								{
									r = i;
									break;
								}
							}
						}
					}
					else
					{
						for (let i=mresult.rowfix; i < mresult._tabledata.length; i++)
						{
							cname = "";
		
							for (let j=0; j < mresult.colfix; j++)
							{
								t = mresult._tabledata[i][j].text || " ";
								cname += t + sep;
							}
		
							if (cname == categname + sep)
							{
								r = i;
								break;
							}
						}
		
						if (seriesname)
						{
							seriesname = IG$.replaceAll(seriesname, "&#x2f;", "/");
							for (let i=mresult.colfix; i < mresult.colcnt; i++)
							{
								cname = "";
		
								for (let j=0; j < mresult.rowfix; j++)
								{
									t = mresult._tabledata[j][i].text || " ";
									t = IG$.replaceAll(t, "&#x2f;", "/");
									cname += t + sep;
								}
		
								if (cname == seriesname + sep)
								{
									c = i;
									break;
								}
							}
						}
						else if (mresult.colfix > 0)
						{
							c = mresult.colfix - 1;
						}
					}
		
					if (c > -1 && r > -1)
					{
						mresult._tabledata[r][c].r = r;
						mresult._tabledata[r][c].c = c;
						this.selectedData.push(mresult._tabledata[r][c]);
					}
				}
			}

			if (me.onClickHandler && me.onClickOwner)
			{
				me.onClickHandler.call(me.onClickOwner, me, sender, param, dragselect);
			}

			if (me.ctrl && me.ctrl.events && me.ctrl.events["itemclick"])
			{
				var pdb = eventowner.ctrl.dashboard,
					actionlist = eventowner.ctrl.actionlist;
				
				pdb.executeAction(actionlist["itemclick"], {
					ctrl: me.ctrl,
					ptr: me,
					event: "itemclick"
				});
			}
		}
	},

