/* file: metricsetting.js */

IG$.metricSetting = $s.extend($s.window, {
	
	modal: true,
	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 480,
	height: 430,
	
	_confirm: function() {
		var me = this;
		
		if (me.item)
		{
			var i,
				optsortdir = me.down("[name=cb_sortdir]"),
				sortorder = optsortdir.getGroupValue(),
				cb_sorttype = me.down("[name=cb_sorttype]"),
				sorttype = me.down("[name=cb_sorttype]").getGroupValue(),
				optstyle = me.down("[name=optstyle]"),
				optremoveblank = me.down("[name=optremoveblank]"),
				isdatetype = me.down("[name=isdatetype]"),
				dateformat = me.down("[name=dateformat]"),
				datenames = IG$.majorDateformat,
				datemap = {},
				ndateitems = "",
				ditems,
				ditem;
			
			
			me.item.sortorder = (sortorder == "") ? null : sortorder;
			me.item.sorttype = (sorttype == "") ? null : sorttype;
			me.item.removeblank = optremoveblank.getValue();
			me.item.stylename = optstyle.getValue();
			me.item.isdatetype = isdatetype.getValue();
			me.item.dateformat = dateformat.getValue();
			
			for (i=0; i < datenames.length; i++)
			{
				if (me.down("[name=datediv_" + datenames[i].name + "]").getValue() == true)
				{
					ndateitems = (ndateitems == "") ? datenames[i].name : ndateitems + ";" + datenames[i];
				}
			}
			
			me.item.dateitems = ndateitems;
			me.item.datecustom = me.down("[name=customdatetype]").getValue();
		}
		
		me.callback && me.callback.execute(me.item);
		
		me.close();
	},
	
	init_f: function() {
		var me = this;
		
		me.formulas = [];
		
		if (me.item)
		{
			me.applyItemInfo();
		}
	},
	
	applyItemInfo: function() {
		var me = this,
			i,
			sortorder = me.item.sortorder || "",
			optsortdir = me.down("[name=optsortdir]"),
			sorttype = me.item.sorttype || "",
			optsorttype = me.down("[name=optsorttype]"),
			optstyle = me.down("[name=optstyle]"),
			optremoveblank = me.down("[name=optremoveblank]"),
			isdatetype = me.down("[name=isdatetype]"),
			dateformat = me.down("[name=dateformat]"),
			datenames = IG$.majorDateformat,
			ditems;
		
		optsortdir.setValue({cb_sortdir: [sortorder]});
		optsorttype.setValue({cb_sorttype: [sorttype]});
		optremoveblank.setValue(me.item.removeblank || false);
		isdatetype.setValue(me.item.isdatetype || false);
		dateformat.setValue(me.item.dateformat || "");
		
		optstyle.setValue(me.item.stylename || "");
		
		if (me.item.dateitems)
		{
			ditems = me.item.dateitems.split(";");
			for (i=0; i < ditems.length; i++)
			{
				me.down("[name=datediv_" + ditems[i] + "]").setValue(true);
			}
		}
		
		me.down("[name=customdatetype]").setValue(me.item.datecustom || "");
	},
	
	changeDateFormat: function() {
		var me = this,
			dateformat = me.down("[name=dateformat]"),
			dt = ""; // optdateformat.getValue();
			
		dateformat.setValue(dt);
	},
	
	initComponent : function() {
		var i, 
			me = this,
			customstyles = [];
			
		me.title = IRm$.r1("T_METRIC_SETTING");
		
		customstyles.push({name: "-Item Default-", value: ""});
		
		if (me.styles && me.styles.length > 0)
		{
			for (i=0; i < me.styles.length; i++)
			{
				customstyles.push({name: me.styles[i].name, value: me.styles[i].name});
			}
		}
		
		$s.apply(me, {
			border: 0,
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					border: 0,
					autoScroll: true,
					defaults: {
						anchor: "100%"
					},
		
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_SORTING"), // "Sorting",
							layout: "anchor",
							padding: ig$.padding,
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "radiogroup",
									name: "optsortdir",
									fieldLabel: IRm$.r1("L_SORT_DIR"),
									plain: true,
									items: [
										{boxLabel: IRm$.r1("B_DEFAULT"), name: "cb_sortdir", inputValue: "", checked: true},
										{boxLabel: IRm$.r1("B_ASC"), name: "cb_sortdir", inputValue: "asc"},
										{boxLabel: IRm$.r1("B_DESC"), name: "cb_sortdir", inputValue: "desc"}
									]
								},
								{
									xtype: "radiogroup",
									name: "optsorttype",
									fieldLabel: IRm$.r1("L_SORT_TYPE"),
									plain: true,
									items: [
										{boxLabel: IRm$.r1("B_DEFAULT"), name: "cb_sorttype", inputValue: "", checked: true},
										{boxLabel: IRm$.r1("B_STRING"), name: "cb_sorttype", inputValue: "VARCHAR"},
										{boxLabel: IRm$.r1("B_NUMERIC"), name: "cb_sorttype", inputValue: "NUMBER"}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_STYLE"), // "Style",
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "combobox",
									name: "optstyle",
									fieldLabel: IRm$.r1("L_BASE_STYLE"),
									queryMode: 'local',
									displayField: 'name',
									valueField: 'value',
									editable: false,
									autoSelect: true,
									store: {
										xtype: 'store',
										fields: [
											"name", "value"
										],
										data: customstyles
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_OTHER_OPTIONS"), // "Other options",
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "checkbox",
									name: "optremoveblank",
									boxLabel: IRm$.r1("L_IGN_BLK_VAL") // "Ignore blank value"
								},
								{
									xtype: "checkbox",
									name: "isdatetype",
									boxLabel: IRm$.r1("L_DT_TYPE_FIELD"), // "Date type field",
									listeners: {
										change: function(field, nvalue, ovalue, eOpts) {
											var me = this,
												isdatetype = field.getValue(),
												datedivision = me.down("[name=datedivision]"),
												customdatetypecontainer = me.down("[name=customdatetypecontainer]"),
												datediv_CUSTOM = me.down("[name=datediv_CUSTOM]");
												
											datedivision.setVisible(isdatetype);
											if (isdatetype == true && datediv_CUSTOM.getValue() == true)
											{
												customdatetypecontainer.setVisible(true);
											}
											else
											{
												customdatetypecontainer.setVisible(false);
											}
										},
										scope: this
									}
								},
								{
									xtype: "fieldcontainer",
									fieldLabel: IRm$.r1("L_DATE_FORMAT"),
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "dateformat",
											flex: 1
										},
										{
											xtype: "button",
											text: IRm$.r1("B_EXAMPLE"), // "Example",
											menu: {
												items: [
													{
														text: "2001.07.04 AM 12:08:56", 
														value: "yyyy.MM.dd a HH:mm:ss",
														handler: function() {
															var dateformat = me.down("[name=dateformat]");
															dateformat.setValue(this.value);
														}
													},
													{
														text: "2001-07-04 AM 12:08:56", 
														value: "yyyy-MM-dd a HH:mm:ss",
														handler: function() {
															var dateformat = me.down("[name=dateformat]");
															dateformat.setValue(this.value);
														}
													},
													{
														text: "Wed, Jul 4, '01", 
														value: "EEE, MMM d, ''yy",
														handler: function() {
															var dateformat = me.down("[name=dateformat]");
															dateformat.setValue(this.value);
														}
													},
													{
														text: "20010704120856", 
														value: "yyyyMMddHHmmss",
														handler: function() {
															var dateformat = me.down("[name=dateformat]");
															dateformat.setValue(this.value);
														}
													}
												]
											}
										}
									]
								}
							]
						},
						{
							fieldLabel: IRm$.r1('L_GROUP_LEVEL'),
							name: "datedivision",
							hidden: true,
							xtype: 'checkboxgroup',
							columns: 3,
							plain: true,
							items: [
								{
									boxLabel: IRm$.r1('B_YEAR'), name: 'datediv_YYYY', inputValue: 'YYYY'
								},
								{
									boxLabel: IRm$.r1('B_QUARTER'), name: 'datediv_QUARTER', inputValue: 'QUARTER'
								},
								{
									boxLabel: IRm$.r1('B_MONTH'), name: 'datediv_MM', inputValue: 'MM'
								},
								{
									boxLabel: IRm$.r1('B_DAY'), name: 'datediv_DD', inputValue: 'DD'
								},
								{
									boxLabel: IRm$.r1('B_WEEKMONTH'), name: 'datediv_WM', inputValue: 'WM'
								},
								{
									boxLabel: IRm$.r1('B_WEEK'), name: 'datediv_WEEK', inputValue: 'WEEK'
								},
								{
									boxLabel: IRm$.r1('B_AMPM'), name: 'datediv_AMPM', inputValue: 'AMPM'
								},
								{
									boxLabel: IRm$.r1('B_HOUR'), name: 'datediv_HH', inputValue: 'HH'
								},
								{
									boxLabel: IRm$.r1('B_MINUTE'), name: 'datediv_MI', inputValue: 'MI'
								},
								{
									boxLabel: IRm$.r1('B_CUSTOM'), 
									name: 'datediv_CUSTOM', 
									inputValue: 'CUSTOM',
									
									listeners: {
										change: function(field, nvalue, ovalue, eOpt) {
											var datediv = field.getValue(),
												customdatetype = this.down("[name=customdatetypecontainer]");
											
											customdatetype.setVisible((datediv == true ? true : false));
										},
										scope: this
									}
								}
							]
						},
						{
							xtype: "fieldcontainer",
							fieldLabel: IRm$.r1('B_CUSTOM'),
							name: "customdatetypecontainer",
							hidden: true,
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									name: "customdatetype",
									flex: 1
								},
								{
									xtype: "button",
									text: IRm$.r1("B_EXAMPLE"), // "Example",
									menu: {
										items: [
											{
												text: "2001.07.04 AM 12:08:56", 
												value: "yyyy.MM.dd a HH:mm:ss",
												handler: function() {
													var dateformat = me.down("[name=customdatetype]");
													dateformat.setValue(this.value);
												}
											},
											{
												text: "2001-07-04 AM 12:08:56", 
												value: "yyyy-MM-dd a HH:mm:ss",
												handler: function() {
													var dateformat = me.down("[name=customdatetype]");
													dateformat.setValue(this.value);
												}
											},
											{
												text: "Wed, Jul 4, '01", 
												value: "EEE, MMM d, ''yy",
												handler: function() {
													var dateformat = me.down("[name=customdatetype]");
													dateformat.setValue(this.value);
												}
											},
											{
												text: "20010704120856", 
												value: "yyyyMMddHHmmss",
												handler: function() {
													var dateformat = me.down("[name=customdatetype]");
													dateformat.setValue(this.value);
												}
											}
										]
									}
								}
							]
						}
					]
				}
			],
			
			buttons:[
				'->',
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],

			listeners: {
				afterrender: function() {
					this.init_f();
				}
			}
		});
		
		IG$.metricSetting.superclass.initComponent.apply(this, arguments);
	}
});