IG$.changeApp = function() {
}

IG$.MainPanel = $s.extend($s.panel, {
	enableTabScroll: true,
	layout: {
		type: "card",
		deferredRender: false
	},
	hidemode: "offset",
	activeTab: 0,
	
	customAddTab: function(uid, ext_panel) {
		var me = this,
			tab = me.getComponent(uid);
			
		if (tab)
		{
			IG$.changeApp(me.instance, 2);
			me.setActiveTab(tab);
		}
		else
		{
			IG$.changeApp(me.instance, 2);
			ext_panel.id = uid;
			tab = me.add(ext_panel);
			me.setActiveTab(tab);
		}
	},
	
	navigateApp: function(uid, itemtype, itemname, itemaddr, baddhistory, writable, option, toption) {
		var me = this,
			instance = me.instance,
			key,
			tab = this.getComponent(itemtype + "_" + uid),
			pitem,
			breadcrumbs = IG$.breadcrumbs,
			breadcrumb = $(".breadcrumb", breadcrumbs.body.dom);
			
		if (tab)
		{
			IG$.changeApp(instance, 2);
			
			this.setActiveTab(tab);
			
			breadcrumb.empty();
			$("<li><span class='link'>" + (tab.title || itemname) + "</span></li>").appendTo(breadcrumb);
			
			if (toption && tab.applyOption)
			{
				tab.applyOption.call(tab, toption);
			}
			
			if (itemtype == "dashboard")
			{
				var teditor = this.getComponent("dashboardedit" + "_" + uid);
				if (teditor)
				{
					if (tab.uid && tab.uid.length > 0)
					{
						tab.procRunDashboard.call(tab);
					}
				}
			}
		}
		else
		{
			toption = toption || {};
			toption.header = false;
			toption._viewmode = "dashboard";
			
			pitem = IG$.createAppPanel(instance, uid, itemtype, itemname, itemaddr, writable, toption);
			
			if (pitem)
			{
				pitem.address = itemaddr;
				pitem.title = itemname; // IG$.getTabTitle(itemname);
				
				breadcrumb.empty();
				$("<li><span class='link'>" + itemname + "</span></li>").appendTo(breadcrumb);
				
				if (option)
				{
					for (key in option)
					{
						pitem[key] = option[key];
					}
				}
				
				if (pitem.isWindow == true)
				{
					if (!IG$.ps[pitem.address])
					{
						IG$.ps[pitem.address] = pitem;
						pitem.on("close", function() {
							delete IG$.ps[pitem.address];
						});
						pitem.show();
					}
				}
				else
				{
					IG$.changeApp(instance, 2);
					pitem.id = itemtype + "_" + uid;
					this.selectedIndex = this.selectedIndex < 0 ? 0 : this.selectedIndex;
					var p = this.add(pitem);
					this.setActiveTab(p);
				}
			}
			else
			{
				baddhistory = false;
			}
		}
		
		if (baddhistory == true)
		{
			lastHist = 'lang=' + useLocale + '&p1=' + itemtype + '&p2=' + uid;
			hist.addHistory(lastHist);
		}
	},
	
	initRecentVisit : function(){
		// when login user changed
	},
	
	updateLoginInfo: function() {
		// when get userdetail finished
		var me = this,
			instance = me.instance,
			viewport = instance.viewport,
			llogin = $("#igc_login_user"),
			ltime,
			lmsg,
			logininfo;
		
		if (instance.dlgLogin && instance.dlgLogin.logininfo)
		{
			logininfo = instance.dlgLogin.logininfo;
			lmsg = logininfo.username;
			llogin.html(lmsg);
			
			IG$.$loadApp(instance, logininfo.tmpl);
			
			if (!instance.dlgLogin.logininfo.__bdmenu)
			{
				instance.dlgLogin.logininfo.__bdmenu = 1;
				llogin.bind("click", function() {
					
				});
			}
			
			if (!viewport._1/*loadInit*/)
			{
				viewport._1/*loadInit*/ = true;
				this.L1/*loadInit*/(viewport);
			}
		}
	},
	
	L1/*loadInit*/: function(viewport) {
		var me = this,
			instance = me.instance,
			navbar = viewport.down("[name=navbar]"),
			sidebar_sc = viewport.down("[name=sidebar_sc]"),
			sidebar = viewport.down("[name=sidebar]"),
			dnavbar = $(navbar.body.dom),
			
			isadmin = instance.dlgLogin.jS2,
			btn;
		
		btn = $("#nav_mgrmenu", dnavbar)[isadmin ? "show" : "hide"]();
		btn.bind("click", function() {
			IG$.procMenuCommand(instance, "CMD_D_MENU");
		});
		
		btn = $(".sidebar-btn-d-menu", sidebar_sc.body.dom);
		btn.bind("click", function() {
			sidebar.getLayout().setActiveItem(0);
		});
		
		btn = $(".sidebar-btn-n-menu", sidebar_sc.body.dom);
		btn.bind("click", function() {
			if (!me.floaded)
			{
				me._1/*loadFavorites*/();
			}
			sidebar.getLayout().setActiveItem(1);
		});
		
		if (!window.hist)
		{
			hist = new IG$.historyManager(instance);
			hist.historyListener();
		}
		
		me.L2/*loadMenu*/(viewport, dnavbar);
	},
	
	L2/*loadMenu*/: function(viewport, dnavbar) {
		var me = this,
			sidebar_m0 = viewport.down("[name=sidebar_m0]"),
			sarea = $("#sidebar", sidebar_m0.body.dom),
			darea = $(".navbar-top-menu", dnavbar),
			nbase = $(".navbar-brand", dnavbar),
			req, snav,
			navbar_dmenu;
		
		if (ig$.theme_id)
		{
			ig$.echarts_theme = ig$.theme_id;
		}
		
		navbar_dmenu = new IG$._menu_button($("#navbar_dmenu"), [], {
			btn_styles: ["fadeInLeft"],
			menu_position: {
				top: 20,
				right: "initial",
				left: 10
			}
		});
		darea.empty();
		
		snav = $("<ul class='igc-smenu-main'></ul>").appendTo(sarea);
		
		req = new IG$._rpc$();
		req.showerror = false;
		req.init(me, 
			{
				ack: "content",
				payload: {uid: "/SYS_Config/dashboardmenu"},
				mbody: {}
			}, me, function(jdoc) {
				var appinfo = jdoc,
					root = appinfo.menustructure,
					unav = $("<div class='igc-tmenu-main'></div>").appendTo(darea),
					vmenus,
					float_menus = [];
					
				nbase.bind("click", function() {
					root[0].options && me._2/*loadPage*/(root[0]);
				});

				me.appinfo = appinfo;
				
				$.each(root, function(n, item) {
					if (n == 0)
						me._active_menu = item;
					var li = $("<div class='igc-tmenu-item'><span class='igc-tnav-item'>" + item.name + "</span><div class='igc-tmenu-act-bar'></div></div>").appendTo(unav);
					li.bind("click", function() {
						snav.empty();
						me.L3/*makeMenu*/(snav, item, 0);
						item.options && me._2/*loadPage*/(item);
					});

					// if (n < root.length - 1)
					// {
					// 	var seph = 10;
					// 	$("<svg width=\"1\" height=\"" + seph + "\" viewBox=\"0 0 1 " + seph + "\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"margin: 15px 8px 0px 16px;\"><line x1=\"0.5\" y1=\"-2.18559e-08\" x2=\"0.500001\" y2=\"" + seph + "\" stroke=\"#E9EAEC\"></line></svg>").appendTo(unav);
					// }
					if (n < root.length - 1)
					{
						li.addClass("mid-menu");
					}
					
					item.html = li;
				});
				
				$.each(root, function(n, item) {
					var fmenu = {
						text: item.name,
						handler: function() {
							item.options && me._2/*loadPage*/(item);
						},
						style: ["dashboard-menu-group"]
					};
					
					float_menus.push(fmenu);
					
					$.each([item.children, item.items], function(j, arr) {
						arr && $.each(arr, function(t, node) {
							var hassub = (!item && node.children && node.children.length > 0) || node.type == "Folder" || (node.items && node.items.length > 0) ? true : false;
							
							if (hassub)
							{
								
							}
							else
							{
								var bmenu = {
									text: node.name,
									handler: function() {
										me.navigateApp(node.uid, node.type.toLowerCase(), node.name, node.nodepath, true, false);
									}
								};
								
								float_menus.push(bmenu);
							}
						});
					});
				});
				
				if (ig$.dashboard_custom && ig$.dashboard_custom.menu_loaded)
				{
					ig$.dashboard_custom.menu_loaded.call(me, root, me, snav);
				}
				
				vmenus = ig$.c_menus;
				
				if (vmenus && vmenus.menus)
				{
					$.each(vmenus.menus, function(n, item) {
						var li = $("<li><span class='igc-tnav-item igc-tnav-citem " + (item.css || "") + "'>" + item.name + "</span></li>").appendTo(unav);
						li.bind("click", function() {
							snav.empty();
							me.L3/*makeMenu*/(snav, item, 0, 1);
						});
					});
				}
				
				navbar_dmenu.setMenus(float_menus);
				
				setTimeout(function() {
					root[0].options && me._2/*loadPage*/(root[0]);
				}, 1000);
				
				//this.L3/*makeMenu*/(unav, root, 0);
			});
		req.send();
	},

	_ltimer: 0,
	_lcitem: 0,

	stopPlay: function() {
		var me = this;

		me._ltimer && clearTimeout(me._ltimer);
		me._ltimer = 0;
	},

	startPlay: function() {
		var me = this;
		me._ltimer && clearTimeout(me._ltimer);
		me._lcitem = 0;
		me._do_play();
	},

	_do_play: function() {
		var me = this,
			_active_menu = me._active_menu;

		if (_active_menu && _active_menu.items && _active_menu.items.length > 1)
		{
			var c = me._lcitem % _active_menu.items.length,
				node = _active_menu.items[c];
			if (node.uid)
				me.navigateApp(node.uid, node.type.toLowerCase(), node.name, node.nodepath, true, false);
		}
		else
		{
			void 0;
			return;
		}

		me._ltimer = setTimeout(function() {
			me._lcitem++;
			me._do_play();
		}, 5000);
	},
	
	L3/*makeMenu*/: function(darea, tnode, level, c_item) {
		var me = this;

		me._active_menu = tnode;

		if (level == 0 && me.appinfo)
		{
			var root = me.appinfo.menustructure;
			$.each(root, function(j, s) {
				if (s == tnode)
				{
					s.html.addClass("active");
				}
				else
				{
					s.html.removeClass("active");
				}
			});
		}
		
		$.each([tnode.children, tnode.items], function(n, arr) {
			arr && $.each(arr, function(t, node) {
				var li = $("<li><div class='indicator'></div></li>").appendTo(darea),
					btn = $("<div class='igc-nav-item'>" + node.name + "</div>").appendTo(li),
					smenu, i,
					sexp,
					hassub = false;
					
				btn.hover(function() {
						$(".indicator", li).addClass("igc-hover");
					},
					function() {
						$(".indicator", li).removeClass("igc-hover");
					}
				);
				
				hassub = (!c_item && node.children && node.children.length > 0) || node.type == "Folder" || (node.items && node.items.length > 0) ? true : false;
				
				if (hassub)
				{
					sexp = $("<div class='igc-submenu-expand'>&gt;</div>").appendTo(li);
					smenu = $("<ul class='submenu'></ul>").appendTo(li);
					smenu.hide();
					
					var mfunc = function(e) {
						e.stopPropagation();
						if (!node.loaded && node.type == "Folder")
						{
							var req = new IG$._rpc$();
							req.init(me, 
								{
									ack: "content",
									payload: {uid: node.uid},
									mbody: {}
								}, me, function(jdoc) {
									var tnodes = (jdoc ? jdoc.children : null),
										i,
										p;
									
									node.items = [];
									node.loaded = true;
										
									if (tnodes)
									{
										for (i=0; i < tnodes.length; i++)
										{
											p = tnodes[i];
											if ((/Report|Folder|Dashboard/).test(p.type))
											{
												node.items.push(p);
											}
										}
										IG$.sortMeta(node.items);
										me.L3/*makeMenu*/(smenu, node, level+1);
										smenu.show();
									}
								});
							req.send();
						}
						else
						{
							smenu.toggle();
						}
					};
					
					sexp.bind("click", mfunc);
					btn.bind("click", mfunc);
					me.L3/*makeMenu*/(smenu, node, level+1);
				}
				else
				{
					if (c_item)
					{
						btn.bind("click", function(e) {
							if (node.handler)
							{
								node.handler.call(this, node);
							}
						});
					}
					else if (node.uid)
					{
						btn.bind("click", function(e) {
							me.navigateApp(node.uid, node.type.toLowerCase(), node.name, node.nodepath, true, false);
						});
					}
				}
			});
		});
	},
	
	setActiveTab: function(tb) {
		this.setActiveItem(tb, true);
	},
	
	_1/*loadFavorites*/: function() {
		var panel=this,
			req = new IG$._rpc$();
		
		req.init(panel, 
			{
				ack: "helpcontent",
				payload: {},
				mbody: {option: 'favorites'}
			}, panel, panel.rs__1/*loadFavorites*/, null, null);
		req.send();
	},
	
	rs__1/*loadFavorites*/: function(xdoc) {
		var me = this,
			i,
			viewport = instance.viewport,
			sidebar_m1 = viewport.down("[name=sidebar_m1]"),
			tnode = IG$.XGetNode(xdoc, "/smsg"),
			tnodes = (tnode) ? IG$.XGetChildNodes(tnode) : null,
			d = [],
			el;
			
		me.floaded = true;
		
		if (tnodes)
		{
			el = $("#sidebar_fav", sidebar_m1.el.dom);
			el = $(".navbar-top-menu", el),
			el.empty();
			
			for (i=0; i < tnodes.length; i++)
			{
				d.push(IG$.XGetAttrProp(tnodes[i]));
			}
			
			me.L3/*makeMenu*/(el, {
					children: null,
					items: d
				}, 0);
		}
	},
	
	_2/*loadPage*/: function(item) {
		var me = this,
			opt = item.options,
			ltype = opt ? opt.ltype : null,
			url,
			req, citem;
		
		if (!ltype)
			return;
			
		switch (ltype)
		{
		case "html":
			url = opt.html;
			url && me._3/*loadHTML*/(item, opt, url);
			break;
		case "report":
			if (opt.rptl_uid)
			{
				if (opt.rptl_item)
				{
					citem = opt.rptl_item;
					me.navigateApp(citem.uid, citem.type.toLowerCase(), citem.name, citem.nodepath, true, false);
				}
				else
				{
					req = new IG$._rpc$();
					req.init(me,
						{
							ack: "helpcontent",
							payload: {uid: opt.rptl_uid},
							mbody: {option: 'translate'}
						}, me, function(jdoc) {
							var me = this,
								citem = jdoc && jdoc.length ? jdoc[0] : null;
		
							if (citem)
							{
								opt.rptl_item = citem;
								me.navigateApp(citem.uid, citem.type.toLowerCase(), citem.name, citem.nodepath, true, false);
							}
						}, false);
					req.send();
				}
			}
			break;
		}
	},
	
	_3/*loadHTML*/: function(item, opt, url) {
		var me = this,
			tid = "tpage_" + item.sid,
			p = this.getComponent(tid);
		
		IG$.changeApp(me.instance, 2);
		
		if (p)
		{
			this.setActiveTab(p);
		}
		else
		{
			p = $s.panel({
				layout: "fit",
				name: tid,
				id: tid,
				autoScroll: true,
				autoLoad: {
					url: url, 
					callback: function() {
						if (opt.scrp && window[opt.scrp])
						{
							var m = this.down("[name=" + tid + "]");
							window[opt.scrp].call(me, item, m);
						}
					}, 
					scope: this
				}
			});
			
			this.add(p);
			this.setActiveTab(p);
		}
	},
	
	//inherit docs
	initComponent: function() {
		var me = this;
		IG$.MainPanel.superclass.initComponent.call(this);
	},
	listeners: {
		beforeadd: function(tobj, component, index, eOpts) {
			component.closable = false;
			component.setTitle(null);
		}
	}
});

IG$.navigateMenuByUID = function(instance, uid, hashtype, param, bhist)
{
	var req = new IG$._rpc$();
	
	req.init(null, 
		{
			ack: "helpcontent",
			payload: {uid: uid},
			mbody: {option: "translate"}
		}, null, function(jdoc) {
			if (jdoc && jdoc.length)
			{
				var node = jdoc[0],
					itemuid = node.uid,
					typename = node.type.toLowerCase(),
					itemname = node.locale_name || node.name,
					itemaddr = node.nodepath,
					writable = false,
					isexport = false; 
					
				if (typename == "export")
				{
					isexport = true;
					typename = "report";
				}
				
				instance.mainPanel.navigateApp.call(instance.mainPanel, itemuid, typename, itemname, itemaddr, (typeof(bhist) == "undefined" ? true : bhist), writable, null, param);
			}
		}, null);
	req.send(instance);
};

